def validate_ordinary_memory_case(spec, grant):
    fields = {'schema','case_id','stage','scope','catalog_reference','retained_table'}
    if (not isinstance(spec,dict) or not isinstance(grant,dict) or set(grant) != fields
            or grant['schema'] != 'frw.bot-tester.ordinary-memory-case.v1'
            or grant['scope'] != MEMORY_SCOPE or grant['catalog_reference'] != MEMORY_CATALOG
            or not isinstance(grant['case_id'],str) or not isinstance(grant['stage'],str)
            or (grant['case_id'],grant['stage']) not in MEMORY_REQUESTS
            or spec.get('kind') != 'ordinary-document-task'
            or spec.get('request') != MEMORY_REQUESTS[(grant['case_id'],grant['stage'])]
            or spec.get('source_reference') is not None or spec.get('output') is not None
            or grant['retained_table'] != (M05_TABLE if grant['case_id'] == 'M-05' else None)):
        raise Refused('Only exact scoped catalog M05/M06/M07 ordinary memory bytes are authorized')
    return grant


