def s06_original_collision_row(raw, run_id, index, upload, now, read_reference):
    """Exact reviewed historical facts only; never a hash/name freshness waiver.

    PRE_REQUEST_REFUSED facts are original pre-wire guard refusals, not sends.
    Their preserved sent_at/dispatch timestamps are intent bookkeeping. The
    exact immutable run plus task custody proves the original no-send branch;
    no ACK/window may be invented and no historical effect is re-admitted.
    """
    historical = next((r for r in S06_ORIGINAL_HISTORY
        if r['run_id'] == run_id and r['step'] == index), None)
    if (upload != S06_INPUTS['FIRST_FILE'] or historical is None
            or digest(raw) != historical['run_sha256']):
        raise Refused('S06 collision is not an exact reviewed immutable historical row')
    record = json.loads(raw,object_pairs_hook=unique_object)
    steps = record.get('scenario',{}).get('steps',[])
    previous = historical['prior_input']
    metadata = record.get('request_metadata',{})
    if (record.get('id') != run_id or len(steps) != 1 or index != 0
            or steps[0].get('input') != previous or previous.get('caption') == upload['caption']
            or record.get('status') != historical['status']
            or record.get('send_state') != historical['send_state']
            or type(record.get('send_attempts')) is not int or record['send_attempts'] != 1
            or type(record.get('repeat_count')) is not int or record['repeat_count'] != 0
            or type(record.get('deadline')) not in (int,float) or not math.isfinite(record['deadline'])
            or type(now) not in (int,float) or not math.isfinite(now) or now <= record['deadline']
            or record['scenario'].get('tester_id') != TESTER or record['scenario'].get('peer_id') != PEER
            or record['scenario'].get('peer_username') != USERNAME
            or record.get('scenario_sha256') != digest(encoded(record['scenario']))
            or metadata.get('scenario_sha256') != record['scenario_sha256']
            or metadata.get('method') != 'sendDocument' or metadata.get('chat_id') != USERNAME
            or metadata.get('caption') != previous['caption'] or metadata.get('filename') != previous['filename']
            or metadata.get('input_sha256') != previous['sha256']
            or metadata.get('input_stat') != previous['stat']
            or metadata.get('input_bytes') != previous['stat']['size_bytes']
            or metadata.get('mime_type') != previous['mime_type']
            or ordinary_input_collisions(upload,previous) != historical['reasons']):
        raise Refused('S06 immutable historical input, route, state or ordinary metadata changed')
    if record['send_state'] == 'sent':
        mid = historical['sent_message_id']
        if (record['status'] != 'EVIDENCE_READY' or type(mid) is not int or mid <= 0
                or record.get('sent_message_id') != mid or record.get('sent_ids') != [mid]
                or record.get('sent_api_ack_reference',{}).get('representation') != 'decoded-message-json'):
            raise Refused('S06 historical confirmed single-send evidence changed')
        read_reference({k:v for k,v in record['sent_api_ack_reference'].items() if k != 'representation'})
        if record.get('sent_window_reference') is not None:
            read_reference(record['sent_window_reference'])
    else:
        if (record['status'] != 'PRE_REQUEST_REFUSED' or record['send_state'] != 'refused_pre_request'
                or record.get('sent_ids') != [] or any(k in record for k in
                    ('sent_message_id','sent_api_ack_reference','sent_window_reference','sent_date'))
                or record.get('observations') != [] or record.get('update_count') != 0
                or record.get('sent_task_reference') is None):
            raise Refused('S06 historical pre-wire no-send evidence changed')
    if record.get('sent_task_reference') is not None:
        if read_reference(record['sent_task_reference']) != metadata:
            raise Refused('S06 historical ordinary task metadata custody changed')
    return dict(run_id=run_id,run_sha256=historical['run_sha256'],step=index,
        prior_input=previous,reasons=historical['reasons'])

def s06_runtime_plan(plan):
    if not isinstance(plan, dict):
        return False
    scenario = plan.get("new_scenario", {}); task = plan.get("new_task", {})
    steps = scenario.get("steps") if isinstance(scenario, dict) else None
    return (isinstance(task, dict) and task.get("kind") == "ordinary-document-task"
        and isinstance(steps, list) and len(steps) == 1 and isinstance(steps[0], dict)
        and any(steps[0].get("input") == source and task.get("request") == source["caption"]
                for source in S06_INPUTS.values()))

