def ordinary_input_collisions(upload, previous):
    """Name every actual collision; physical identity is never waivable."""
    return [name for name, hit in (
        ('sha256', upload['sha256'] == previous['sha256']),
        ('path', upload['path'] == previous['path']),
        ('path_basename', Path(upload['path']).name == Path(previous['path']).name),
        ('filename', upload['filename'] == previous['filename']),
        ('inode', (upload['stat']['device'],upload['stat']['inode']) ==
                  (previous['stat']['device'],previous['stat']['inode']))) if hit]


