def s12_original_grant(plan, tester_sha):
    raw_materials = safe_read(Path(S12_COLLISION_MATERIALS['path']))
    if digest(raw_materials) != S12_COLLISION_MATERIALS['sha256']:
        raise Refused('S12 frozen collision inventory changed')
    materials = json.loads(raw_materials, object_pairs_hook=unique_object)
    records = materials.get('records') if isinstance(materials, dict) else None
    if (materials.get('schema') != 'frw.Root.s12-frozen-input-collision-materials.v1'
            or not isinstance(records, list) or len(records) != 14):
        raise Refused('S12 exact fourteen frozen collision records required')
    collisions, admissions = [], []
    for item in records:
        frozen = item['frozen']
        raw = safe_read(Path(frozen['path']))
        if digest(raw) != frozen['sha256']:
            raise Refused('S12 frozen collision bytes changed')
        value = json.loads(raw, object_pairs_hook=unique_object)
        if item['kind'] == 'run':
            run_id = value.get('id')
            previous = value.get('scenario', {}).get('steps', [{}])[0].get('input')
            if (run_id != Path(frozen['path']).name.removeprefix('run-').removesuffix('.json')
                    or not isinstance(previous, dict)
                    or s12_original_run(value)):
                raise Refused('S12 frozen run identity or original-effect absence changed')
            collisions.append(dict(run_id=run_id, run_sha256=frozen['sha256'], step=0,
                prior_input=previous, reasons=ordinary_input_collisions(S12_ORIGINAL_INPUT, previous)))
        elif item['kind'] == 'admission':
            admitted = value.get('plan', {})
            if (value.get('status') != 'ONE_NEW_EFFECT_ADMITTED_NO_RETRY'
                    or value.get('plan_sha256') != digest(encoded(admitted))
                    or s12_original_effect(admitted.get('new_task'), admitted.get('new_scenario'))):
                raise Refused('S12 frozen admission or original-effect absence changed')
            admissions.append(dict(basename=Path(item['original']['path']).name,
                sha256=frozen['sha256'], bytes=len(raw)))
        else:
            raise Refused('S12 unknown frozen collision record kind')
    if len(collisions) != 7 or len(admissions) != 7:
        raise Refused('S12 exact seven runs and seven admissions required')
    return dict(schema='frw.bot-tester.s12-original-input.v1', operator='Root', case='S-12',
        decision='ONE_DISTINCT_S12_LAYOUT_EXACT_SHARED_ORIGINAL_INPUT',
        plan_sha256=digest(encoded(plan)), tester_sha256=tester_sha,
        predecessor=plan['predecessor'], current_tuple=S12_CURRENT_TUPLE,
        input=S12_ORIGINAL_INPUT, request=S12_REQUEST,
        history_materials=S12_COLLISION_MATERIALS, collisions=collisions, admissions=admissions,
        old_effects_and_clocks_preserved=True, old_send_replay_authorized=False,
        product_acceptance=False)


def validate_m04_input(operation, upload):
    expected = M04_INPUTS.get(operation)
    if not expected or not isinstance(upload,dict):
        raise Refused('Exact M04 input operation required')
    validate_document_input(upload)
    if any(upload[k] != v for k,v in expected.items()):
        raise Refused('M04 cannot change prepared path, native name, bytes, MIME or caption')
    return upload


