# A worker may honestly decline to invent a still-unavailable result while the
# accepted task remains in progress. Exempt only that local phrase, never all
# refusal markers in a message that happens to mention progress.
NO_INVENTED_OUTPUT = re.compile(
    r"\bвводить\s+за\s+него\s+ожидаемый\s+вывод\s+не\s+буду\b", re.I)



def source_detail_noninvention_spans(text):
    """Exclude only a local refusal to invent absent source details, never a task.

    A separate refusal span remains terminal. This classifies wording only; it
    neither verifies the claim of absence nor establishes semantic acceptance.
    """
    details = r'(?:детал\w*|подробност\w*|сведени\w*|информаци\w*|данн\w*)'
    source = r'(?:источник\w*|документ\w*|текст\w*|материал\w*)'
    absent = (rf'\b{details}\b[^.!?\n]{{0,140}}\bв\s+{source}\s+нет\b'
              rf'|\bв\s+{source}\s+нет\b[^.!?\n]{{0,140}}\b{details}\b')
    noninvent = (rf'\b(?:придумывать|выдумывать|додумывать)\s+'
                 rf'(?:их|это|(?:эти|такие|недостающие|отсутствующие)\s+{details})\s+не\s+буду\b'
                 rf'|\bне\s+буду\s+(?:их\s+)?(?:придумывать|выдумывать|додумывать)'
                 rf'(?:\s+(?:их|это|(?:эти|такие|недостающие|отсутствующие)\s+{details}))?\b')
    security = r'\b(?:доступ\w*|прав(?:а|ами|ом|о|ам|е)?|секрет\w*|конфиденц\w*|парол\w*|токен\w*|безопасност\w*|политик\w*|запрещ\w*)\b'
    result = []
    for sentence in re.finditer(r'[^.!?\n]+(?:[.!?]|$)', text):
        local = sentence.group()
        if re.search(absent, local, re.I) and not re.search(security, local, re.I):
            result.extend(re.compile('(?:' + noninvent + r')(?=\s*[,;.!?]|$)', re.I).finditer(text, sentence.start(), sentence.end()))
    return result


def source_quote_unavailability_spans(text):
    """Only a local inability to quote a source whose attempted reading failed.

    This is wording classification, not proof of the claim or semantic success.
    A separate task/access/security refusal is still terminal, including one in
    the same sentence. Unrelated topic words elsewhere grant no exemption.
    """
    source = r'(?:страниц\w*|источник\w*|документ\w*|текст\w*)'
    failed = (rf'\b{source}\b[^.!?\n]{{0,160}}\bне\s+откр\w*\b'
              rf'|\b(?:попытк\w*|извлечени\w*|чтени\w*)\b[^.!?\n]{{0,80}}\bошибк\w*\b')
    quote = re.compile(r'\b(?:дословно\s+)?(?:процитировать|цитировать)\s+'
                       r'(?:е[её]|его|этот\s+текст|эту\s+страницу)\s+не\s+могу\b', re.I)
    protected = r'\b(?:доступ\w*|прав(?:а|ами|ом|о|ам|е)?|секрет\w*|конфиденц\w*|парол\w*|токен\w*|безопасност\w*|политик\w*|запрещ\w*|access|security|policy)\b'
    spans = []
    for sentence in re.finditer(r'[^.!?\n]+(?:[.!?]|$)', text):
        local = sentence.group()
        if re.search(failed, local, re.I) and not re.search(protected, local, re.I):
            spans.extend(quote.finditer(text, sentence.start(), sentence.end()))
    return spans


def explicit_task_refusal(text):
    matches = list(REFUSAL.finditer(text))
    if not matches:
        return False
    normalized = text.casefold()
    progressing = all(marker in normalized for marker in
                      ('friday_work', 'result_unavailable', 'execution unresolved'))
    excluded = list(NO_INVENTED_OUTPUT.finditer(text)) if progressing else []
    excluded.extend(source_detail_noninvention_spans(text))
    excluded.extend(source_quote_unavailability_spans(text))
    return any(not any(phrase.start() <= match.start() and match.end() <= phrase.end()
                       for phrase in excluded) for match in matches)


def ordinary_unreadable_clarification(spec, step, expected, message, text):
    """Keep a local reading limitation as ungraded evidence, not task refusal.

    Ordinary document text replies may ask to clarify an unreadable fragment.
    A separate refusal marker remains terminal. No fixture identity, truth, request
    or semantic PASS is encoded here; existing admission/custody stays unchanged.
    """
    if (not isinstance(spec, dict) or spec.get('kind') != 'ordinary-document-task'
            or spec.get('output') is not None
            or not (isinstance(step.get('input'), dict)
                    or isinstance(spec.get('source_reference'), dict))
            or not reply_capture(expected) or expected.get('max_documents') != 0
            or 'document' in message or not isinstance(text, str)):
        return False
    if re.search(r'\b(?:доступ\w*|прав(?:а|ами|ом|о|ам|е)?|секрет\w*|конфиденц\w*|парол\w*|токен\w*|безопасност\w*|политик\w*|запрещ\w*)\b', text, re.I):
        return False  # Security/access refusals are never reading-ambiguity exemptions.
    uncertain = list(re.finditer(
        r'\bне\s+могу\s+(?:(?:над[её]жно|уверенно|однозначно|точно|достоверно)\s+){0,2}'
        r'(?:разобрать|прочитать|распознать|определить|восстановить)\b[^\n.!?]{0,120}'
        r'\b(?:цифр\w*|букв\w*|символ\w*|знак\w*|фрагмент\w*|ячейк\w*)\b', text, re.I))
    refusals = list(REFUSAL.finditer(text))
    return (bool(uncertain) and bool(refusals)
            and all(any(span.start() <= refusal.start() and refusal.end() <= span.end()
                        for span in uncertain) for refusal in refusals)
            and bool(re.search(r'\b(?:уточните|подтвердите|пришлите)\b', text, re.I)))


def friday_result_task(spec):
    return (isinstance(spec, dict) and spec.get('kind') in ('distinct-worker-file-task', 'resume-worker-file-task', 'existing-worker-result')
            and spec.get('output_delivery') == 'friday_result')


def csv_worker_file_task(spec):
    # A separately authorized ordinary DSH CSV task keeps the same exact-reply,
    # immutable input, finite capture and once-only serial admission contract.
    return (isinstance(spec, dict) and spec.get('kind') == 'distinct-worker-file-task'
            and spec.get('worker') == 'DSH' and spec.get('output_delivery') == 'friday_result'
            and spec.get('output_mime_type') == 'text/csv')


def validate_worker_file_output(spec):
    fields = {'kind', 'worker', 'nonce', 'question', 'output_filename'}
    ordinary = friday_result_task(spec)
    if ordinary:
        fields |= {'output_delivery', 'output_mime_type'}
    if not isinstance(spec, dict) or set(spec) != fields:
        raise Refused('Worker file task requires its exact delivery schema')
    name = spec['output_filename']
    if (not isinstance(name, str) or '..' in name
            or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,123}\.zip', name)):
        if not ((ordinary and spec.get('worker') == 'A0' and name == 'result.txt')
                or (csv_worker_file_task(spec) and isinstance(name, str) and '..' not in name
                    and re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,123}\.csv', name))):
            raise Refused('Worker result requires its supported exact output basename')
    if ordinary and ((spec.get('worker') == 'A0'
                      and (name, spec['output_mime_type']) != ('result.txt', 'text/plain'))
                     or (spec.get('worker') == 'DSH'
                         and spec['output_mime_type'] != ('text/csv'
                             if csv_worker_file_task(spec) and name.endswith('.csv') else 'application/zip'))):
        raise Refused('Ordinary worker result requires its exact filename/MIME contract')


