class Refused(Exception):
    pass


class ReplyWindowClosed(Refused):
    """Validated fixed window closed before a network dispatch budget was issued."""
    pass


class Uncertain(Refused):
    def __init__(self, *args, cause_code='TRANSPORT_OUTCOME_UNKNOWN', phase_code='SEND_API_CALL'):
        super().__init__(*args)
        # Only owned local deadline sites opt in; timing never establishes cause.
        self.cause_code = (cause_code if cause_code in (
            'LOCAL_HTTP_ALARM_DEADLINE', 'LOCAL_HTTP_BODY_DEADLINE',
            'TRANSPORT_TIMEOUT', 'TRANSPORT_URL_FAILURE', 'TRANSPORT_OS_FAILURE')
            else 'TRANSPORT_OUTCOME_UNKNOWN')
        self.phase_code = phase_code if phase_code in (
            'HTTP_WHOLE_CALL', 'HTTP_REQUEST_OR_HEADERS', 'HTTP_RESPONSE_BODY',
            'HTTP_RESPONSE_STATUS', 'HTTP_RESPONSE_ENVELOPE', 'SEND_API_CALL') else 'SEND_API_CALL'


def send_failure_diagnostic(exc, phase='SEND_API_CALL'):
    # Fixed diagnostic vocabulary only. Never serialize exception text/reason/URL.
    phases = {'HTTP_WHOLE_CALL', 'HTTP_REQUEST_OR_HEADERS', 'HTTP_RESPONSE_BODY',
              'HTTP_RESPONSE_STATUS', 'HTTP_RESPONSE_ENVELOPE', 'SEND_API_CALL'}
    causes = {'LOCAL_HTTP_ALARM_DEADLINE', 'LOCAL_HTTP_BODY_DEADLINE',
              'HTTP_STATUS_3XX', 'HTTP_STATUS_4XX', 'HTTP_STATUS_5XX', 'HTTP_STATUS_OTHER',
              'TRANSPORT_TIMEOUT', 'TRANSPORT_URL_FAILURE', 'TRANSPORT_OS_FAILURE',
              'TRANSPORT_OUTCOME_UNKNOWN'}
    phase = phase if type(phase) is str and phase in phases else 'SEND_API_CALL'
    if isinstance(exc, urllib.error.HTTPError):
        status = exc.code
        category = status // 100 if type(status) is int else None
        return ('HTTP_STATUS_' + str(category) + 'XX' if category in (3, 4, 5)
                else 'HTTP_STATUS_OTHER'), 'HTTP_RESPONSE_STATUS'
    if isinstance(exc, TimeoutError):
        return 'TRANSPORT_TIMEOUT', phase
    if isinstance(exc, urllib.error.URLError):
        return ('TRANSPORT_TIMEOUT' if isinstance(exc.reason, TimeoutError)
                else 'TRANSPORT_URL_FAILURE'), phase
    if isinstance(exc, OSError):
        return 'TRANSPORT_OS_FAILURE', phase
    if isinstance(exc, Refused):
        code = getattr(exc, 'cause_code', None)
        supplied_phase = getattr(exc, 'phase_code', None)
        return (code if type(code) is str and code in causes else 'TRANSPORT_OUTCOME_UNKNOWN',
                supplied_phase if type(supplied_phase) is str and supplied_phase in phases else phase)
    return 'TRANSPORT_OUTCOME_UNKNOWN', phase


class RateLimited(Refused):
    def __init__(self, seconds):
        self.seconds = seconds
        super().__init__('Telegram rate limit; cooldown recorded')


def network_deadline_available():
    if (threading.current_thread() is not threading.main_thread()
            or signal.getitimer(signal.ITIMER_REAL) != (0.0, 0.0)):
        raise Refused('Network deadline requires exclusive main-thread alarm ownership before intent')


@contextlib.contextmanager
def network_deadline(seconds):
    """Linux CLI total deadline, including DNS, TLS, body, and error body reads."""
    if threading.current_thread() is not threading.main_thread() or seconds <= 0:
        raise Refused('Network requires main thread and positive total deadline')
    previous = signal.getsignal(signal.SIGALRM)
    previous_timer = signal.getitimer(signal.ITIMER_REAL)
    if previous_timer != (0.0, 0.0):
        raise Refused('Existing process alarm prevents safe network deadline ownership')
    def expired(signum, frame):
        raise Uncertain('Whole HTTP deadline expired; preserve uncertain send',
                        cause_code='LOCAL_HTTP_ALARM_DEADLINE', phase_code='HTTP_WHOLE_CALL')
    signal.signal(signal.SIGALRM, expired)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        yield
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous)
        signal.setitimer(signal.ITIMER_REAL, *previous_timer)


def stamp():
    return dt.datetime.now(dt.timezone.utc).isoformat()


def digest(data):
    return hashlib.sha256(data).hexdigest()


def encoded(value):
    return (json.dumps(value, ensure_ascii=True, sort_keys=True) + '\n').encode()


def no_symlinks(path):
    path = Path(os.path.abspath(path))
    for part in (path, *path.parents):
        if part.is_symlink():
            raise Refused('Symlink path refused')
    return path


def secure_dir(path):
    path = no_symlinks(path)
    path.mkdir(mode=0o700, parents=True, exist_ok=True)
    s = path.stat()
    if not stat.S_ISDIR(s.st_mode) or s.st_uid != os.getuid() or stat.S_IMODE(s.st_mode) != 0o700:
        raise Refused('Private directory requires owner and mode 0700')
    return path


def safe_read(path, limit=MAX_JSON, private=True):
    path = no_symlinks(path)
    if not path.exists() and str(path).startswith('/home/jericho/.cache/'):
        # The disk cleanup of 2026-11-08 removed the retained Root evidence under
        # /home/jericho/.cache. The bytes of a removed document cannot be re-derived and
        # are not re-asserted: the caller records the unavailable Root facts instead of
        # claiming them. The retained run records and capture files stay the evidence.
        raise Refused('Root evidence removed by the disk cleanup of 2026-11-08: '
                      + str(path))
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(fd, 'rb') as f:
        s = os.fstat(f.fileno())
        if not stat.S_ISREG(s.st_mode) or s.st_nlink != 1 or s.st_size > limit:
            raise Refused('Unsafe file type, link count, or size')
        if private and (s.st_uid != os.getuid() or stat.S_IMODE(s.st_mode) != 0o600):
            raise Refused('Private file requires owner and mode 0600')
        data = f.read(limit + 1)
    if len(data) > limit:
        raise Refused('File too large')
    return data


def reply_text_of(message):
    """The model's own wording of one reply, with the field it came from.

    A reply that carries a document has a caption instead of a text field. Both are the
    model's own wording; neither is invented here. The choice is deterministic and the
    source is returned with the text, so the protected receipt records which field was
    used and the reader checks exactly that field again.

    The rules, in order:
      * a non-empty string 'text' is the wording, source 'text';
      * otherwise a non-empty string 'caption' is the wording, source 'caption';
      * otherwise the reply has no wording at all, source None and the text is absent.

    An empty string is not wording: it is treated as absent, so a receipt never claims an
    empty text it cannot re-derive.
    """
    if not isinstance(message, dict):
        return None, None
    value = message.get('text')
    if isinstance(value, str) and value:
        return value, 'text'
    value = message.get('caption')
    if isinstance(value, str) and value:
        return value, 'caption'
    return None, None


def bounded_capture(value):
    return isinstance(value, dict) and value.get('mode') == 'bounded_capture'


def reply_capture(value):
    return isinstance(value, dict) and value.get('mode') == 'bounded_reply_capture'


def validate_capture(value):
    fields = {'mode', 'max_bytes', 'filename_equals', 'mime_type_equals', 'caption_equals'}
    if not isinstance(value, dict) or set(value) != fields or not bounded_capture(value):
        raise Refused('Bounded capture requires its exact explicit schema; no hash or wildcard')
    if type(value['max_bytes']) is not int or not 1 <= value['max_bytes'] <= MAX_FILE:
        raise Refused('Bounded capture requires the original finite byte cap')
    name = value['filename_equals']
    try:
        valid_name = (isinstance(name, str) and 1 <= len(name) <= 128
                      and len(name.encode('utf-8')) <= 512
                      and name == unicodedata.normalize('NFC', name)
                      and name == name.strip() and name not in ('.', '..')
                      and '..' not in name and '/' not in name and chr(92) not in name
                      and all(not unicodedata.category(c).startswith('C') for c in name))
    except UnicodeError:
        valid_name = False
    if not valid_name:
        raise Refused('Capture filename requires a safe bounded NFC Unicode basename')
    if (not isinstance(value['mime_type_equals'], str)
            or not re.fullmatch(r'[a-z0-9][a-z0-9!#$&^_.+-]{0,63}/[a-z0-9][a-z0-9!#$&^_.+-]{0,63}', value['mime_type_equals'])):
        raise Refused('Capture requires an exact bounded MIME selector')
    caption = value['caption_equals']
    try:
        valid_caption = (isinstance(caption, str) and len(caption) <= 1024
                         and len(caption.encode('utf-8')) <= 4096 and chr(0) not in caption)
    except UnicodeError:
        valid_caption = False
    if not valid_caption:
        raise Refused('Capture requires an exact bounded caption selector')
    return value


S15_OUTPUT = dict(contract='s15-original-roundtrip-four.v1')
S15_CAPTURE = dict(mode='bounded_reply_capture', window_seconds=180,
                   max_messages=12, max_text_chars=8000, max_documents=4,
                   document_max_bytes=8388608,
                   artifact_contract='s15-original-roundtrip-four.v1')
S15_XLSX_MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
S16_XLSX_MIME = S15_XLSX_MIME
S16_OUTPUT = dict(contract='s16-original-untrusted-table-one.v1')
S16_CAPTURE = dict(mode='bounded_reply_capture', window_seconds=180,
                   max_messages=12, max_text_chars=8000, max_documents=1,
                   document_max_bytes=8388608,
                   artifact_contract='s16-original-untrusted-table-one.v1')
S16_MIME_TYPES = frozenset((S16_XLSX_MIME, 'text/csv', 'text/tab-separated-values'))


def ordinary_s15_roundtrip(value):
    return isinstance(value, dict) and value == S15_OUTPUT


def ordinary_s16_untrusted_table(value):
    return isinstance(value, dict) and value == S16_OUTPUT


def ordinary_s15_reply_capture(value, *, max_window_seconds=600):
    if not isinstance(value, dict) or 'artifact_contract' not in value:
        return None
    if encoded(value) != encoded(S15_CAPTURE) or value['window_seconds'] > max_window_seconds:
        raise Refused('Only the exact S15 four-artifact capture schema is supported')
    return value


def ordinary_s16_reply_capture(value, *, max_window_seconds=600):
    if not isinstance(value, dict) or value.get('artifact_contract') != S16_OUTPUT['contract']:
        return None
    if value != S16_CAPTURE or value['window_seconds'] > max_window_seconds:
        raise Refused('Only the exact S16 one-artifact capture schema is supported')
    return value


def validate_reply_capture(value, *, max_window_seconds=600):
    s16 = ordinary_s16_reply_capture(value, max_window_seconds=max_window_seconds)
    if s16 is not None:
        return s16
    s15 = ordinary_s15_reply_capture(value, max_window_seconds=max_window_seconds)
    if s15 is not None:
        return s15
    fields = {'mode', 'window_seconds', 'max_messages', 'max_text_chars',
              'max_documents', 'document_max_bytes'}
    if not isinstance(value, dict) or set(value) != fields or not reply_capture(value):
        raise Refused('Bounded reply capture requires its exact closed schema; no selectors or wildcards')
    for field, low, high in [('window_seconds', 1, max_window_seconds), ('max_messages', 1, 64),
                             ('max_text_chars', 1, 8000), ('max_documents', 0, 4),
                             ('document_max_bytes', 1, MAX_FILE)]:
        if type(value.get(field)) is not int or not low <= value[field] <= high:
            raise Refused('Bounded reply capture bound invalid: ' + field)
    return value


def ordinary_optional_xlsx_output(value):
    # Explicit singleton opt-in. Historical two-key output descriptors stay required.
    return (isinstance(value, dict) and set(value) == {'filename', 'mime_type', 'required'}
            and value['required'] is False and value['mime_type'] == UPLOAD_TYPES['xlsx'])


def ordinary_s14_report_delivery(value, observations=None):
    """Exact S14 transport descriptor; narrative semantics stay external.

    Two capture slots permit one mandatory PDF and a distinct readable document,
    or the PDF plus independent chat narrative. No format or filename is asked
    of the user. No content extracted from the PDF counts as chat narrative.
    """
    descriptor = dict(filename=None, mime_type='application/pdf',
                      narrative='separate-chat-or-readable-document.v1')
    if value != descriptor:
        return None
    if observations is None:
        return [dict(filename=None, mime_type='application/pdf'),
                dict(filename=None, mime_type='text/plain')]
    documents = [o for o in observations if o.get('kind') == 'document']
    pdfs, narratives = [], []
    text_types = {'text/plain', 'text/csv', UPLOAD_TYPES['docx']}
    for item in documents:
        actual = item.get('advertised_document', {})
        mime = actual.get('mime_type'); name = actual.get('file_name')
        # No filename/extension is required by the original request. Preserve
        # any supplied safe basename; actual bytes and manual review establish
        # readability/type. A suffix never overrides the advertised MIME.
        if name is not None:
            try:
                validate_capture(dict(mode='bounded_capture', max_bytes=MAX_FILE,
                    filename_equals=name, mime_type_equals=mime, caption_equals=''))
            except (Refused, TypeError, ValueError, AttributeError):
                return ['S14_DOCUMENT_METADATA_MISMATCH']
        if mime == 'application/pdf':
            pdfs.append(item)
        elif mime in text_types:
            narratives.append(item)
        else:
            return ['S14_UNSUPPORTED_NARRATIVE_CARRIER']
    if len(pdfs) != 1 or len(narratives) > 1 or len(documents) > 2:
        return ['S14_ONE_ACTUAL_PDF_REQUIRED']
    if not narratives and not any(o.get('kind') == 'reply_text'
            and isinstance(o.get('text'), str) and o['text'].strip() for o in observations):
        return ['S14_SEPARATE_NARRATIVE_REQUIRED']
    return []


def ordinary_s15_file_identity(item):
    doc, info = item.get('advertised_document'), item.get('get_file')
    return (type(doc) is dict and type(info) is dict
            and all(type(doc.get(name)) is str and 1 <= len(doc[name]) <= 512
                    and info.get(name) == doc[name] for name in ('file_id', 'file_unique_id'))
            and type(item.get('bytes')) is int
            and type(doc.get('file_size')) is int and type(info.get('file_size')) is int
            and 0 <= item['bytes'] == doc['file_size'] == info['file_size'])


def ordinary_s15_shared_workbook(previous, received, expectation):
    """One stable Telegram file may have two distinct actual XLSX deliveries."""
    return (encoded(expectation) == encoded(S15_CAPTURE)
            and all(type(item) is dict and item.get('kind') == 'document'
                    and ordinary_s15_file_identity(item)
                    and item['advertised_document'].get('mime_type') == S15_XLSX_MIME
                    and item.get('complete_artifact') is True
                    and type(item.get('sha256')) is str
                    and re.fullmatch('[a-f0-9]{64}', item['sha256']) is not None
                    for item in (previous, received))
            and previous['sha256'] == received['sha256']
            and previous['bytes'] == received['bytes']
            and (previous['advertised_document']['file_id'] != received['advertised_document']['file_id']
                 or previous['advertised_document']['file_unique_id'] == received['advertised_document']['file_unique_id'])
            and previous.get('run_id') == received.get('run_id')
            and all(previous.get(name) is not None and received.get(name) is not None
                    and previous[name] != received[name]
                    for name in ('message_id', 'update_id', 'path', 'receipt_sha256')))


def ordinary_s15_document_failures(documents):
    if len(documents) != 4 or any(not isinstance(item, dict) for item in documents):
        return ['S15_FOUR_DISTINCT_ARTIFACTS_REQUIRED']
    expected = {'text/csv': 1, 'text/tab-separated-values': 1, S15_XLSX_MIME: 2}
    actual = {}
    for item in documents:
        doc = item.get('advertised_document', {})
        if type(doc) is not dict:
            return ['S15_DOCUMENT_METADATA_MISMATCH']
        mime = doc.get('mime_type')
        if type(mime) is not str:
            return ['S15_DOCUMENT_METADATA_MISMATCH']
        actual[mime] = actual.get(mime, 0) + 1
        name = doc.get('file_name')
        try:
            if name is not None:
                validate_capture(dict(mode='bounded_capture', max_bytes=MAX_FILE,
                    filename_equals=name, mime_type_equals=mime, caption_equals=''))
        except (Refused, TypeError, ValueError, AttributeError):
            return ['S15_DOCUMENT_METADATA_MISMATCH']
        if (not ordinary_s15_file_identity(item)
                or item.get('complete_artifact') is not True
                or item.get('artifact_acceptance') != 'RECEIVED_UNGRADED'
                or item.get('acceptance') != 'NOT_ESTABLISHED'
                or encoded(item.get('declared_selectors')) != encoded(S15_CAPTURE)
                or type(item.get('bytes')) is not int or item['bytes'] < 0
                or not isinstance(item.get('sha256'), str)
                or re.fullmatch('[a-f0-9]{64}', item['sha256']) is None):
            return ['S15_COMPLETE_UNGRADED_RECEIPT_REQUIRED']
    if actual != expected:
        return ['S15_EXACT_CSV_TSV_TWO_XLSX_MIME_MULTISET_REQUIRED']
    identities = [(item.get('update_id'), item.get('message_id'),
                   item.get('advertised_document', {}).get('file_unique_id'),
                   item.get('sha256'), item.get('path'), item.get('receipt_sha256')) for item in documents]
    if any(any(value is None for value in identity) for identity in identities):
        return ['S15_RECEIPT_IDENTITY_REQUIRED']
    # Identical workbook bytes may be valid for two independently returned legs.
    # Distinct ingress/path/receipt custody is mandatory; file IDs identify files.
    if (any(type(item.get('update_id')) is not int or item['update_id'] < 0
            or type(item.get('message_id')) is not int or item['message_id'] <= 0
            or type(item.get('receipt_sha256')) is not str
            or re.fullmatch('[a-f0-9]{64}', item['receipt_sha256']) is None
            for item in documents)
            or any(type(item.get('run_id')) is not str or not item['run_id']
                   or type(item.get('path')) is not str or not item['path']
                   or type(item.get('advertised_document', {}).get('file_unique_id')) is not str
                   or not item['advertised_document']['file_unique_id'] for item in documents)
            or len({item.get('run_id') for item in documents}) != 1):
        return ['S15_RECEIPT_IDENTITY_REQUIRED']
    for index in (0, 1, 4, 5):
        if len({identity[index] for identity in identities}) != 4:
            return ['S15_DUPLICATE_OR_AMBIGUOUS_ARTIFACT_IDENTITY']
    for index, item in enumerate(documents):
        current = item['advertised_document']
        for previous in documents[:index]:
            prior = previous['advertised_document']
            if (any(prior[name] == current[name] for name in ('file_id', 'file_unique_id'))
                    and not ordinary_s15_shared_workbook(previous, item, S15_CAPTURE)):
                return ['S15_SHARED_FILE_IDENTITY_CONTENT_OR_CUSTODY_MISMATCH']
    return []


def ordinary_s16_document_failures(documents):
    if len(documents) != 1 or not isinstance(documents[0], dict):
        return ['S16_EXACTLY_ONE_ARTIFACT_REQUIRED']
    item = documents[0]; doc = item.get('advertised_document', {})
    mime = doc.get('mime_type'); name = doc.get('file_name')
    try:
        if name is not None:
            validate_capture(dict(mode='bounded_capture', max_bytes=MAX_FILE,
                filename_equals=name, mime_type_equals=mime, caption_equals=''))
    except (Refused, TypeError, ValueError, AttributeError):
        return ['S16_DOCUMENT_METADATA_MISMATCH']
    if mime not in S16_MIME_TYPES:
        return ['S16_PRODUCT_CHOSEN_MUST_BE_XLSX_CSV_OR_TSV']
    if (item.get('complete_artifact') is not True
            or item.get('artifact_acceptance') != 'RECEIVED_UNGRADED'
            or item.get('acceptance') != 'NOT_ESTABLISHED'
            or item.get('declared_selectors') != S16_CAPTURE
            or type(item.get('bytes')) is not int or not 0 < item['bytes'] <= S16_CAPTURE['document_max_bytes']
            or not isinstance(item.get('sha256'), str)
            or re.fullmatch('[a-f0-9]{64}', item['sha256']) is None):
        return ['S16_COMPLETE_UNGRADED_RECEIPT_REQUIRED']
    identity = (item.get('update_id'), item.get('message_id'), doc.get('file_unique_id'), item.get('path'))
    if any(value is None for value in identity):
        return ['S16_RECEIPT_IDENTITY_REQUIRED']
    return []


def ordinary_presentation_roles(value):
    if not isinstance(value, list) or len(value) != 2:
        return None
    if any(not isinstance(item, dict) or set(item) != {'filename', 'mime_type'}
           or item['filename'] is not None for item in value):
        return None
    roles = frozenset(item['mime_type'] for item in value)
    allowed = (frozenset((UPLOAD_TYPES['pptx'], UPLOAD_TYPES['pdf'])),
               frozenset((UPLOAD_TYPES['odp'], UPLOAD_TYPES['pptx'])))
    return roles if roles in allowed else None


def _presentation_native_kind(data):
    if not isinstance(data, bytes) or len(data) > 8388608:
        return None
    if data.startswith(b'%PDF-') and data.rstrip().endswith(b'%%EOF'):
        return 'pdf'
    import posixpath
    from xml.etree import ElementTree as ET
    import zlib

    def xml(package, name):
        raw = package.read(name)
        if not raw or len(raw) > 1000000 or b'<!DOCTYPE' in raw.upper() or b'<!ENTITY' in raw.upper():
            raise ValueError('unsafe XML')
        return ET.fromstring(raw)

    def relationships(root):
        namespace = 'http://schemas.openxmlformats.org/package/2006/relationships'
        if root.tag != '{%s}Relationships' % namespace:
            raise ValueError('relationship namespace')
        result = []
        for rel in root:
            if (rel.tag != '{%s}Relationship' % namespace or not rel.get('Id')
                    or not rel.get('Type') or not rel.get('Target')):
                raise ValueError('relationship structure')
            result.append(rel)
        return result

    try:
        with ZipFile(io.BytesIO(data)) as package:
            infos = package.infolist()
            names = [info.filename for info in infos]
            if (not infos or len(infos) > 512 or len({name.casefold() for name in names}) != len(names)
                    or sum(info.file_size for info in infos) > 16777216):
                return None
            for info in infos:
                parts = info.filename.split('/')
                if (not info.filename or info.filename.startswith('/') or '\\' in info.filename
                        or '\x00' in info.filename or any(part in ('', '.', '..') for part in parts[:-1])
                        or any(part in ('.', '..') for part in parts[-1:])
                        or info.flag_bits & 1 or info.compress_type not in (0, 8)
                        or info.file_size > 2097152
                        or info.file_size > max(4096, info.compress_size * 200)):
                    return None
            if 'ppt/presentation.xml' in names:
                required = {'[Content_Types].xml', '_rels/.rels', 'ppt/_rels/presentation.xml.rels'}
                if not required <= set(names):
                    return None
                content_namespace = 'http://schemas.openxmlformats.org/package/2006/content-types'
                content = xml(package, '[Content_Types].xml')
                if content.tag != '{%s}Types' % content_namespace:
                    return None
                defaults = {}; overrides = {}
                for node in content:
                    if not node.get('ContentType'):
                        return None
                    if node.tag == '{%s}Default' % content_namespace:
                        extension = node.get('Extension', '').lower()
                        if not re.fullmatch(r'[a-z0-9]+', extension) or extension in defaults:
                            return None
                        defaults[extension] = node.get('ContentType')
                    elif node.tag == '{%s}Override' % content_namespace:
                        part = node.get('PartName', '')
                        if not part.startswith('/') or '..' in part or part in overrides:
                            return None
                        overrides[part] = node.get('ContentType')
                    else:
                        return None
                for name in names:
                    if name.endswith('/') or name == '[Content_Types].xml':
                        continue
                    if '/'+name not in overrides and name.rsplit('.', 1)[-1].lower() not in defaults:
                        return None
                presentation_type = 'application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml'
                slide_type = 'application/vnd.openxmlformats-officedocument.presentationml.slide+xml'
                if overrides.get('/ppt/presentation.xml') != presentation_type:
                    return None
                office = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
                roots = [rel for rel in relationships(xml(package, '_rels/.rels'))
                         if rel.get('Type') == office+'/officeDocument']
                if len(roots) != 1 or roots[0].get('Target') != 'ppt/presentation.xml' or roots[0].get('TargetMode', 'Internal') != 'Internal':
                    return None
                pns = 'http://schemas.openxmlformats.org/presentationml/2006/main'
                presentation = xml(package, 'ppt/presentation.xml')
                if presentation.tag != '{%s}presentation' % pns:
                    return None
                slide_ids = presentation.findall('./{%s}sldIdLst/{%s}sldId' % (pns, pns))
                if not 1 <= len(slide_ids) <= 200:
                    return None
                slide_rels = {}
                for rel in relationships(xml(package, 'ppt/_rels/presentation.xml.rels')):
                    if rel.get('Type') == office+'/slide':
                        if rel.get('Id') in slide_rels or rel.get('TargetMode', 'Internal') != 'Internal':
                            return None
                        slide_rels[rel.get('Id')] = rel.get('Target')
                visited = set()
                for slide in slide_ids:
                    rid = slide.get('{%s}id' % office)
                    if rid not in slide_rels:
                        return None
                    target = posixpath.normpath(posixpath.join('ppt', slide_rels[rid]))
                    if target.startswith('../') or target in visited or '/'+target not in overrides:
                        return None
                    if overrides['/'+target] != slide_type or xml(package, target).tag != '{%s}sld' % pns:
                        return None
                    visited.add(target)
                return 'pptx'
            if 'mimetype' in names or 'content.xml' in names:
                if (infos[0].filename != 'mimetype' or infos[0].compress_type != 0
                        or package.read('mimetype') != b'application/vnd.oasis.opendocument.presentation'
                        or not {'content.xml', 'META-INF/manifest.xml'} <= set(names)):
                    return None
                mns = 'urn:oasis:names:tc:opendocument:xmlns:manifest:1.0'
                manifest = xml(package, 'META-INF/manifest.xml')
                if manifest.tag != '{%s}manifest' % mns or manifest.findall('.//{%s}encryption-data' % mns):
                    return None
                entries = manifest.findall('{%s}file-entry' % mns)
                roots = [node for node in entries if node.get('{%s}full-path' % mns) == '/']
                if len(roots) != 1 or roots[0].get('{%s}media-type' % mns) != 'application/vnd.oasis.opendocument.presentation':
                    return None
                ons = 'urn:oasis:names:tc:opendocument:xmlns:office:1.0'
                dns = 'urn:oasis:names:tc:opendocument:xmlns:drawing:1.0'
                content = xml(package, 'content.xml')
                if content.tag != '{%s}document-content' % ons:
                    return None
                presentation = content.find('./{%s}body/{%s}presentation' % (ons, ons))
                if presentation is None or not 1 <= len(presentation.findall('./{%s}page' % dns)) <= 200:
                    return None
                return 'odp'
    except (BadZipFile, KeyError, RuntimeError, OSError, ValueError, ET.ParseError,
            UnicodeError, NotImplementedError, EOFError, zlib.error):
        return None
    return None


def ordinary_presentation_document_failures(output, documents):
    roles = ordinary_presentation_roles(output)
    if roles is None:
        return ['PRESENTATION_ROLE_DESCRIPTOR_REQUIRED']
    if len(documents) != 2:
        return ['PRESENTATION_EXACTLY_TWO_ARTIFACTS_REQUIRED']
    observed = []
    identities = []
    for item in documents:
        if not isinstance(item, dict):
            return ['PRESENTATION_COMPLETE_UNGRADED_RECEIPT_REQUIRED']
        doc = item.get('advertised_document', {})
        mime = doc.get('mime_type'); name = doc.get('file_name')
        try:
            validate_capture(dict(mode='bounded_capture', max_bytes=MAX_FILE,
                filename_equals=name, mime_type_equals=mime, caption_equals=''))
            selectors = item.get('declared_selectors')
            validate_reply_capture(selectors)
        except (Refused, TypeError, ValueError, AttributeError):
            return ['PRESENTATION_DOCUMENT_METADATA_OR_CAPTURE_MISMATCH']
        extension = name.rsplit('.', 1)[-1].lower() if '.' in name else ''
        if (mime not in roles or UPLOAD_TYPES.get(extension) != mime
                or selectors.get('max_documents') != 2):
            return ['PRESENTATION_EXACT_ROLE_MULTICAST_REQUIRED']
        if (item.get('complete_artifact') is not True
                or item.get('artifact_acceptance') != 'RECEIVED_UNGRADED'
                or item.get('acceptance') != 'NOT_ESTABLISHED'
                or type(item.get('bytes')) is not int
                or not 0 < item['bytes'] <= selectors['document_max_bytes']
                or not isinstance(item.get('sha256'), str)
                or re.fullmatch('[a-f0-9]{64}', item['sha256']) is None):
            return ['PRESENTATION_COMPLETE_UNGRADED_RECEIPT_REQUIRED']
        identity = (item.get('update_id'), item.get('message_id'),
                    doc.get('file_unique_id'), item.get('path'))
        if any(value is None for value in identity):
            return ['PRESENTATION_RECEIPT_IDENTITY_REQUIRED']
        try:
            data = safe_read(item['path'], selectors['document_max_bytes'])
        except (Refused, OSError):
            return ['PRESENTATION_SAFE_ARTIFACT_CUSTODY_REQUIRED']
        if len(data) != item['bytes'] or digest(data) != item['sha256']:
            return ['PRESENTATION_ARTIFACT_HASH_OR_SIZE_MISMATCH']
        kind = _presentation_native_kind(data)
        if kind is None or UPLOAD_TYPES[kind] != mime:
            return ['PRESENTATION_NATIVE_BYTES_MIME_MISMATCH']
        observed.append(mime)
        identities.append((item['sha256'], doc['file_unique_id'], item['path']))
    if frozenset(observed) != roles or len(set(observed)) != 2:
        return ['PRESENTATION_EXACT_ROLE_MULTICAST_REQUIRED']
    if any(len({identity[index] for identity in identities}) != 2 for index in range(3)):
        return ['PRESENTATION_DUPLICATE_OR_AMBIGUOUS_ARTIFACT_IDENTITY']
    return []


def ordinary_document_outputs(value):
    if ordinary_s16_untrusted_table(value):
        return [dict(filename=None, mime_type=None,
                     allowed_mime_types=sorted(S16_MIME_TYPES), exactly_one=True)]
    if ordinary_s15_roundtrip(value):
        return [dict(filename=None, mime_type='text/csv', direction='xlsx_to_csv'),
                dict(filename=None, mime_type='text/tab-separated-values', direction='xlsx_to_tsv'),
                dict(filename=None, mime_type=S15_XLSX_MIME, direction='csv_to_xlsx'),
                dict(filename=None, mime_type=S15_XLSX_MIME, direction='tsv_to_xlsx')]
    s14 = ordinary_s14_report_delivery(value)
    if s14 is not None:
        return s14
    if value is None:
        return []
    multiple = isinstance(value, list)
    outputs = value if multiple else [value]
    if (multiple and not 2 <= len(outputs) <= 4) or not 1 <= len(outputs) <= 4:
        raise Refused('Ordinary task requires one output or two to four declared outputs')
    optional = not multiple and ordinary_optional_xlsx_output(value)
    for output in outputs:
        if (not isinstance(output, dict)
                or (set(output) != {'filename', 'mime_type'} and not optional)
                or output['mime_type'] not in UPLOAD_TYPES.values()):
            raise Refused('Declared catalogue document output required')
        if output['filename'] is not None:
            validate_capture(dict(mode='bounded_capture', max_bytes=MAX_FILE,
                filename_equals=output['filename'], mime_type_equals=output['mime_type'], caption_equals=''))
            extension = output['filename'].rsplit('.', 1)[-1].lower()
            if '.' not in output['filename'] or UPLOAD_TYPES.get(extension) != output['mime_type']:
                raise Refused('Declared output extension/MIME mismatch')
    explicit_names = [output['filename'] for output in outputs if output['filename'] is not None]
    if len(set(explicit_names)) != len(explicit_names):
        raise Refused('Declared multiple output filenames must be distinct')
    return outputs


def ordinary_unordered_output_failures(outputs, documents):
    """At most four ungraded artifacts; natural filenames need no prompt rewrite.

    Each independently received file must retain its complete custody and exact
    bytes. Matching roles concerns transport only, never semantic acceptance.
    """
