    # SHA is mandatory, while distinct ingress, paths and file identities bind
    # the files; their semantic differences require the original case oracle.
    if any(len({identity[i] for identity in identities}) != len(outputs) for i in range(1,5)):
        return ['MULTI_ARTIFACT_DUPLICATE_IDENTITY']
