def ordinary_document_output_failures(output, documents):
    if ordinary_s16_untrusted_table(output):
        return ordinary_s16_document_failures(documents)
    if ordinary_s15_roundtrip(output):
        return ordinary_s15_document_failures(documents)
    if ordinary_s14_report_delivery(output) is not None:
        return ordinary_s14_report_delivery(output, documents)
    if ordinary_presentation_roles(output) is not None:
        return ordinary_presentation_document_failures(output, documents)
    outputs = ordinary_document_outputs(output)
    if not outputs:
        return []
    if isinstance(output, list) and (len(outputs) > 2 or any(item['filename'] is None for item in outputs)):
        return ordinary_unordered_output_failures(outputs, documents)
    if ordinary_optional_xlsx_output(output) and not documents:
        return []  # Text clarification is valid evidence; semantic review stays mandatory.
    if len(documents) != len(outputs):
        return ['EXPECTED_DOCUMENT_MISSING']
    if len(outputs) == 1:
        actual = documents[0].get('advertised_document', {})
        return [] if (actual.get('mime_type') == outputs[0]['mime_type']
                      and (outputs[0]['filename'] is None
                           or actual.get('file_name') == outputs[0]['filename'])) else ['EXPECTED_DOCUMENT_METADATA_MISMATCH']
    expected = sorted(((item['mime_type'], item['filename']) for item in outputs),
                      key=lambda item: (item[0] or '', item[1] or ''))
    actual = sorted(((item.get('advertised_document', {}).get('mime_type'),
                      item.get('advertised_document', {}).get('file_name')) for item in documents),
                    key=lambda item: (item[0] or '', item[1] or ''))
    return [] if actual == expected else ['EXPECTED_DOCUMENT_METADATA_MISMATCH']


