def ordinary_ambiguous_join_clarification(spec, step, expected, message, text):
    """Capture a scoped join clarification UNGRADED; never a semantic exemption.

    Only local inability to choose/join ambiguous data is eligible. Every refusal
    marker must be in such a clause; security/account/policy/task refusals remain
    terminal. Output optionality by itself does not exempt any refusal.
    """
    if (not isinstance(spec, dict) or spec.get('kind') != 'ordinary-document-task'
            or not ordinary_optional_xlsx_output(spec.get('output'))
            or not (isinstance(step.get('input'), dict)
                    or isinstance(spec.get('source_reference'), dict))
            or not reply_capture(expected) or expected.get('max_documents') != 1
            or 'document' in message or not isinstance(text, str)):
        return False
    if re.search(r'\b(?:доступ\w*|прав(?:а|ами|ом|о|ам|е)?|секрет\w*|конфиденц\w*|парол\w*|токен\w*|безопасност\w*|политик\w*|запрещ\w*|запрет\w*|аккаунт\w*|уч[её]тн\w*|авторизац\w*|аутентификац\w*|полномоч\w*|разрешени\w*|администратор\w*|access|security|policy|account|credential\w*|login|authentication|permission\w*|authoriz\w*|password\w*|token\w*|confidential\w*|secret\w*)\b', text, re.I):
        return False
    if not re.search(r'\b(?:уточните|подтвердите|како[йеую]\s+(?:вариант|правило)|какого\s+поставщика)\b', text, re.I):
        return False
    eligible = []
    local = re.compile(r'\bне\s+могу\s+(?:(?:однозначно|корректно|достоверно|точно)\s+){0,2}'
        r'(?:выбрать|сопоставить|соединить|объединить|определить|выполнить\s+(?:соединение|объединение))\b', re.I)
    for sentence in re.finditer(r'[^.!?\n]+(?:[.!?]|$)', text):
        clause = sentence.group()
        if (re.search(r'\b(?:неоднознач\w*|дубл\w*|дважды|несколько\s+(?:соответстви\w*|поставщик\w*|вариант\w*))\b', clause, re.I)
                and re.search(r'\b(?:поставщик\w*|соответстви\w*|строк\w*|соединени\w*|объединени\w*)\b', clause, re.I)):
            eligible.extend(local.finditer(text, sentence.start(), sentence.end()))
    refusals = list(REFUSAL.finditer(text))
    return (bool(eligible) and bool(refusals)
            and all(any(span.start() <= refusal.start() and refusal.end() <= span.end()
                        for span in eligible) for refusal in refusals))


