def input_stat(s):
    return dict(zip(INPUT_STAT_FIELDS, (s.st_dev, s.st_ino, s.st_size, s.st_uid,
                                       s.st_mtime_ns, s.st_ctime_ns)))


def read_document_input(value, guard):
    """Open every path component relative to its parent FD; never follow links.

    The same final FD supplies both reads and all before/after metadata. A second
    root-relative open checks that the pinned path still names that same file.
    """
    validate_document_input(value)
    def open_source():
        current = os.open('/', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        try:
            parts = value['path'].split('/')[1:]
            for part in parts[:-1]:
                following = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                                    dir_fd=current)
                os.close(current)
                current = following
            return os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
                           dir_fd=current)
        finally:
            os.close(current)
    def check(fd):
        s = os.fstat(fd)
        if (not stat.S_ISREG(s.st_mode) or s.st_nlink != 1 or s.st_uid != os.getuid()
                or input_stat(s) != value['stat']):
            raise Refused('Document source identity or metadata drift; nothing sent')
        return s
    def read(fd):
        chunks, total = [], 0
        while True:
            guard()
            part = os.read(fd, min(65536, MAX_UPLOAD + 1 - total))
            if not part:
                break
            chunks.append(part)
            total += len(part)
            if total > MAX_UPLOAD:
                raise Refused('Document input exceeds original byte cap')
        return b''.join(chunks)
    try:
        guard()
        fd = open_source()
        try:
            check(fd)
            data = read(fd)
            check(fd)
            if len(data) != value['stat']['size_bytes'] or digest(data) != value['sha256']:
                raise Refused('Document input size or hash drift; nothing sent')
            os.lseek(fd, 0, os.SEEK_SET)
            reread = read(fd)
            check(fd)
            if len(reread) != len(data) or digest(reread) != value['sha256']:
                raise Refused('Document input changed during verification; nothing sent')
            second = open_source()
            try:
                check(second)
            finally:
                os.close(second)
            guard()
            return data
        finally:
            os.close(fd)
    except OSError:
        raise Refused('Document source could not be safely opened; nothing sent') from None


def photo_dimensions(value, data):
    """Validate bounded PNG/JPEG structure and declared dimensions, not pixels.

    The Bot API decodes the uploaded photo. Its recompressed bytes do not prove
    source-byte equality; original multipart custody and the photo ACK stay separate.
    """
    if value.get('kind') != 'photo':
        raise Refused('Explicit photo input required')
    if value['mime_type'] == 'image/png':
        if not data.startswith(b'\x89PNG\r\n\x1a\n'):
            raise Refused('Photo PNG signature mismatch')
        pos=8; dimensions=None; image_data=False; ended=False
        while pos < len(data):
            if pos+12 > len(data):raise Refused('Truncated photo PNG chunk')
            size=int.from_bytes(data[pos:pos+4],'big');kind=data[pos+4:pos+8]
            if size > len(data)-pos-12:raise Refused('Truncated photo PNG payload')
            payload=data[pos+8:pos+8+size]
            if zlib.crc32(kind+payload)&0xffffffff != int.from_bytes(data[pos+8+size:pos+12+size],'big'):
                raise Refused('Photo PNG CRC mismatch')
            if dimensions is None:
                if kind != b'IHDR' or size != 13:raise Refused('Photo PNG first header required')
                dimensions=(int.from_bytes(payload[:4],'big'),int.from_bytes(payload[4:8],'big'))
            elif kind == b'IHDR':raise Refused('Duplicate photo PNG header')
            if kind in (b'acTL',b'fcTL',b'fdAT'):raise Refused('Animated photo input unsupported')
            if kind == b'IDAT':image_data=True
            pos+=size+12
            if kind == b'IEND':
                if size or pos != len(data):raise Refused('Photo PNG trailing data refused')
                ended=True;break
        if not dimensions or not image_data or not ended:raise Refused('Incomplete photo PNG')
    elif value['mime_type'] == 'image/jpeg':
        if not data.startswith(b'\xff\xd8') or not data.endswith(b'\xff\xd9'):
            raise Refused('Photo JPEG signature mismatch')
        pos=2;dimensions=None;scan=False;segments=0
        while pos < len(data)-2 and segments < 512:
            if data[pos] != 255:raise Refused('Photo JPEG marker required')
            while pos < len(data) and data[pos] == 255:pos+=1
            if pos >= len(data):raise Refused('Truncated photo JPEG marker')
            marker=data[pos];pos+=1;segments+=1
            if marker in (0,0xd8,0xd9)or 0xd0 <= marker <= 0xd7:raise Refused('Unexpected photo JPEG marker')
            if pos+2 > len(data):raise Refused('Truncated photo JPEG segment')
            size=int.from_bytes(data[pos:pos+2],'big')
            if size < 2 or pos+size > len(data)-2:raise Refused('Photo JPEG segment bound')
            payload=data[pos+2:pos+size]
            if marker in (0xc0,0xc2):
                if (dimensions is not None or len(payload)<6 or payload[0]!=8
                        or payload[5]not in(1,3)or len(payload)!=6+3*payload[5]):
                    raise Refused('Photo JPEG frame unsupported')
                dimensions=(int.from_bytes(payload[3:5],'big'),int.from_bytes(payload[1:3],'big'))
            elif 0xc0 <= marker <= 0xcf and marker not in (0xc4,0xc8,0xcc):
                raise Refused('Photo JPEG coding unsupported')
            if marker==0xda:
                if not dimensions or len(payload)<4 or len(payload)!=4+2*payload[0]or pos+size>=len(data)-2:
                    raise Refused('Photo JPEG scan header required')
                scan=True;break
            pos+=size
        if not dimensions or not scan:raise Refused('Incomplete photo JPEG')
    else:raise Refused('Photo MIME unsupported')
    width,height=dimensions
    if min(width,height)<=0 or width+height>10000 or max(width,height)>20*min(width,height):
        raise Refused('Photo dimensions exceed admitted Bot API bounds')
    return dimensions


