def document_multipart(value, data):
    validate_document_input(value)
    if (not isinstance(data, bytes) or len(data) != value['stat']['size_bytes']
            or digest(data) != value['sha256']):
        raise Refused('Multipart bytes do not match the exact input pin')
    if value['kind'] == 'photo':photo_dimensions(value,data)
    # Candidate boundaries are deterministic, bounded, and checked against all
    # values; there is no accidental delimiter even for adversarial binary input.
    boundary = None
    for i in range(16):
        candidate = 'frw-' + digest(data + str(i).encode())
        if all(candidate.encode() not in part for part in (data, value['caption'].encode('utf-8'),
                                                           value['filename'].encode(), value['mime_type'].encode())):
            boundary = candidate
            break
    if boundary is None:
        raise Refused('Could not select a safe multipart boundary')
    pieces = []
    for name, content in (('chat_id', USERNAME.encode()), ('caption', value['caption'].encode('utf-8'))):
        pieces.append(('--' + boundary + '\r\nContent-Disposition: form-data; name="' + name
                       + '"\r\n\r\n').encode() + content + b'\r\n')
    field = 'photo' if value['kind']=='photo' else 'document'
    pieces.append(('--' + boundary + '\r\nContent-Disposition: form-data; name="' + field + '"; filename="'
                   + value['filename'] + '"\r\nContent-Type: ' + value['mime_type']
                   + '\r\n\r\n').encode() + data + b'\r\n')
    pieces.append(('--' + boundary + '--\r\n').encode())
    body = b''.join(pieces)
    if len(body) > MAX_UPLOAD + MAX_MULTIPART_OVERHEAD or len(body) - len(data) > MAX_MULTIPART_OVERHEAD:
        raise Refused('Multipart body overhead bound exceeded')
    return body, 'multipart/form-data; boundary=' + boundary


class Store:
    def __init__(self, root):
        self.root = secure_dir(root)
        self.runs = secure_dir(self.root / 'runs')
        self.captures = secure_dir(self.root / 'updates')
        self.downloads = secure_dir(self.root / 'downloads')

    def write(self, path, data):
        path = no_symlinks(path)
        if path.exists():
            safe_read(path, max(MAX_JSON, MAX_FILE, len(data)))
        tmp = path.with_name(path.name + '.new')
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        try:
            with os.fdopen(fd, 'wb') as f:
                f.write(data)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, path)
            fd = os.open(path.parent, os.O_DIRECTORY)
            try:
                os.fsync(fd)
            finally:
                os.close(fd)
        finally:
            if tmp.exists():
                tmp.unlink()

    def put(self, path, value):
        self.write(path, encoded(value))

    def get(self, path, default=None):
        return json.loads(safe_read(path), object_pairs_hook=unique_object) if path.exists() else default

    @contextlib.contextmanager
    def lock(self, path=None, create=True):
        path = no_symlinks(path or self.root / 'consumer.lock')
        fd = os.open(path, os.O_RDWR | (os.O_CREAT if create else 0) | os.O_NOFOLLOW, 0o600)
        try:
            s = os.fstat(fd)
            if not stat.S_ISREG(s.st_mode) or s.st_nlink != 1 or s.st_uid != os.getuid() or stat.S_IMODE(s.st_mode) != 0o600:
                raise Refused('Unsafe lock file')
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                raise Refused('Another tester consumer is active') from None
            yield fd
        finally:
            os.close(fd)

    def run_path(self, name):
        if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,63}', name):
            raise Refused('Run ID requires 1-64 simple characters')
        return self.runs / (name + '.json')


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *args, **kwargs):
        raise Refused('Redirect refused')


class BotAPI:
    def __init__(self, token):
        if not re.fullmatch(r'8812646969:[A-Za-z0-9_-]{20,100}', token):
            raise Refused('Token prefix must match pinned tester')
        self._token = token
        self.opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect())

    def _read(self, url, body, timeout, limit, content_type='application/json'):
        with network_deadline(timeout):
            return self._request(url, body, timeout, limit, content_type)

    def _request(self, url, body, timeout, limit, content_type='application/json'):
        request = urllib.request.Request(url, data=body, headers={'Content-Type': content_type})
        expires = time.monotonic() + timeout
        try:
            with self.opener.open(request, timeout=max(0.1, timeout)) as response:
                if response.geturl() != url:
                    raise Refused('Unexpected response URL')
                chunks, size = [], 0
                try:
                    while True:
                        if time.monotonic() >= expires:
                            raise Uncertain('Network deadline expired; outcome unknown',
                                            cause_code='LOCAL_HTTP_BODY_DEADLINE', phase_code='HTTP_RESPONSE_BODY')
                        # read1 performs at most one buffered/socket read, so a drip-fed
                        # response cannot extend the deadline by filling a large read.
                        chunk = response.read1(min(65536, limit + 1 - size))
                        if not chunk:
                            break
                        chunks.append(chunk)
                        size += len(chunk)
                        if size > limit:
                            refused = Refused('Response size bound exceeded')
                            refused.bounded_body = b''.join(chunks)[:limit]
                            refused.received_at_least = size
                            raise refused
                    data = b''.join(chunks)
                except Uncertain as uncertain:
                    # Timeout/alarm/transport failures keep the capped received prefix as
                    # evidence; the original terminal failure still propagates, never retried.
                    if not isinstance(getattr(uncertain, 'bounded_body', None), bytes):
                        uncertain.bounded_body = b''.join(chunks)[:limit]
                        uncertain.received_at_least = size
                    raise
                except (urllib.error.URLError, TimeoutError, OSError) as exc:
                    if isinstance(exc, urllib.error.HTTPError):
                        raise
                    # Mid-read resets/timeouts keep the capped received prefix as evidence.
                    code, phase = send_failure_diagnostic(exc, 'HTTP_RESPONSE_BODY')
                    uncertain = Uncertain('Transport outcome unknown; never blindly resend',
                                          cause_code=code, phase_code=phase)
                    if size:
                        uncertain.bounded_body = b''.join(chunks)[:limit]
                        uncertain.received_at_least = size
                    raise uncertain from None
        except urllib.error.HTTPError as exc:
            try:
                try:
                    data = exc.read(MAX_JSON + 1)
                    value = json.loads(data) if len(data) <= MAX_JSON else {}
                    retry = value.get('parameters', {}).get('retry_after')
                    if exc.code == 429 and type(retry) is int and 0 < retry <= 86400:
                        raise RateLimited(retry) from None
                except (ValueError, TypeError):
                    pass
                refused = Refused('Telegram HTTP rejection; response intentionally withheld')
                refused.cause_code, refused.phase_code = send_failure_diagnostic(exc)
                raise refused from None
            finally:
                # Python 3.14 warns on implicit HTTPError cleanup using repr(msg).
                # The reason is server-controlled and may contain a credential.
                exc.close()
        except (urllib.error.URLError, TimeoutError, OSError) as exc:
            code, phase = send_failure_diagnostic(exc, 'HTTP_REQUEST_OR_HEADERS')
            raise Uncertain('Transport outcome unknown; never blindly resend',
                            cause_code=code, phase_code=phase) from None
        if len(data) > limit:
            raise Refused('Response size bound exceeded')
        return data

    def call(self, method, params=None, timeout=10):
        if method not in METHODS:
            raise Refused('API method refused')
        data = self._read('https://api.telegram.org/bot' + self._token + '/' + method,
                          encoded(params or {}), timeout, MAX_JSON)
        return self._result(data)

    def _result(self, data):
        self._last_response = data  # Bounded wire envelope, for exact private acknowledgement custody.
        try:
            value = json.loads(data)
            if not isinstance(value, dict):
                raise Refused('Malformed Telegram response')
            if value.get('ok') is not True:
                parameters = value.get('parameters', {})
                retry = parameters.get('retry_after') if isinstance(parameters, dict) else None
                if value.get('error_code') == 429 and type(retry) is int and 0 < retry <= 86400:
                    raise RateLimited(retry)
                raise Refused('Telegram API rejected request')
            return value['result']
        except (ValueError, KeyError, TypeError):
            raise Refused('Malformed Telegram response') from None

    def send_document(self, body, content_type, timeout=10):
        if (not isinstance(body, bytes) or len(body) > MAX_UPLOAD + MAX_MULTIPART_OVERHEAD
                or not isinstance(content_type, str)
                or not re.fullmatch(r'multipart/form-data; boundary=frw-[a-f0-9]{64}', content_type)):
            raise Refused('Only bounded prepared multipart document uploads are allowed')
        data = self._read('https://api.telegram.org/bot' + self._token + '/sendDocument',
                          body, timeout, MAX_JSON, content_type)
        return self._result(data)

    def send_photo(self, body, content_type, timeout=10):
        if (not isinstance(body, bytes) or len(body) > MAX_UPLOAD + MAX_MULTIPART_OVERHEAD
                or not isinstance(content_type, str)
                or not re.fullmatch(r'multipart/form-data; boundary=frw-[a-f0-9]{64}', content_type)):
            raise Refused('Only bounded prepared multipart photo uploads are allowed')
        data = self._read('https://api.telegram.org/bot' + self._token + '/sendPhoto',
                          body, timeout, MAX_JSON, content_type)
        return self._result(data)

    def download(self, file_path, max_bytes, timeout=10):
        if not isinstance(file_path, str) or not re.fullmatch(r'[A-Za-z0-9_/.-]{1,240}', file_path) or any(p in ('', '.', '..') for p in file_path.split('/')):
            raise Refused('Unsafe Telegram file path')
        return self._read('https://api.telegram.org/file/bot' + self._token + '/' + file_path,
                          None, timeout, max_bytes)


def valid_document_ack(message):
    doc = message.get('document')
    if not isinstance(doc, dict):
        return False
    for field in ('file_id', 'file_unique_id'):
        if not isinstance(doc.get(field), str) or not 1 <= len(doc[field]) <= 1024:
            return False
    if 'file_size' in doc and (type(doc['file_size']) is not int or not 0 <= doc['file_size'] <= MAX_FILE):
        return False
    return all(key not in doc or isinstance(doc[key], str) and len(doc[key]) <= 512
               for key in ('file_name', 'mime_type'))


def valid_photo_ack(message):
    if not isinstance(message,dict) or 'document' in message:return False
    photos=message.get('photo')
    if not isinstance(photos,list)or not 1<=len(photos)<=16:return False
    for photo in photos:
        if (not isinstance(photo,dict)
                or any(not isinstance(photo.get(k),str)or not 1<=len(photo[k])<=1024
                       for k in('file_id','file_unique_id'))
                or any(type(photo.get(k))is not int or not 1<=photo[k]<=10000 for k in('width','height'))
                or ('file_size'in photo and(type(photo['file_size'])is not int or not 0<photo['file_size']<=MAX_FILE))):
            return False
    return len({p['file_unique_id']for p in photos})==len(photos)


def valid_input_ack(message,upload,*,require_document_size=False):
    if not isinstance(message,dict)or not caption_ack_matches(message.get('caption',''),upload['caption']):
        return False
    if upload['kind']=='photo':return valid_photo_ack(message)
    if upload['kind']!='document'or 'photo'in message or not valid_document_ack(message):return False
    doc=message['document']
    return (doc.get('file_size')==upload['stat']['size_bytes']if require_document_size
            else 'file_size'not in doc or doc['file_size']==upload['stat']['size_bytes'])


def preflight(api, timeout=10, guard=None):
    expires = time.monotonic() + timeout
    def budget():
        remaining = expires - time.monotonic()
        if guard is not None:
            guarded = guard()
            remaining = min(expires - time.monotonic(), guarded)
        if remaining <= 0:
            raise Refused('Preflight deadline expired')
        return remaining
    me = api.call('getMe', timeout=budget())
    if me.get('is_bot') is not True or type(me.get('id')) is not int or me['id'] != TESTER or me['id'] == PEER:
        raise Refused('Authenticated identity is not pinned tester bot')
    webhook = api.call('getWebhookInfo', timeout=budget())
    if webhook.get('url') != '':
        raise Refused('Tester has webhook; do not delete or replace it')
    peer = api.call('getChat', {'chat_id': USERNAME}, timeout=budget())
    if peer.get('id') != PEER or peer.get('type') != 'private':
        raise Refused('Authenticated target lookup numeric peer mismatch')
    return {'tester_id': me['id'], 'is_bot': True, 'webhook_empty': True,
            'peer_id': peer['id'], 'mode_verified': False,
            'note': 'Both bot modes require external operator confirmation'}


def stopped1578_capture_scenario(scenario):
    # Schema support only. Extended capture still requires the exact protected
    # stopped1578 admission at both new-run and every dispatch guard boundary.
    if not isinstance(scenario, dict):
        return False
    steps = scenario.get('steps')
    return (scenario.get('deadline_seconds') == 1800
            and scenario.get('max_updates') == 64 and scenario.get('pace_seconds') == 2
            and isinstance(steps, list) and len(steps) == 1
            and isinstance(steps[0], dict) and set(steps[0]) == {'request', 'observe'}
            and steps[0]['observe'] == dict(mode='bounded_reply_capture',
                window_seconds=1200, max_messages=12, max_text_chars=8000,
                max_documents=1, document_max_bytes=1048576))


def validate_scenario(scenario):
    if not isinstance(scenario, dict) or scenario.get('peer_id') != PEER or scenario.get('tester_id') != TESTER or scenario.get('peer_username') != USERNAME:
        raise Refused('Scenario numeric identities and username must be pinned')
    for field, low, high in [('deadline_seconds', 10, 1800), ('max_updates', 1, 200), ('pace_seconds', 1, 60)]:
        if type(scenario.get(field)) is not int or not low <= scenario[field] <= high:
            raise Refused('Scenario bound invalid: ' + field)
    steps = scenario.get('steps')
    if not isinstance(steps, list) or not 1 <= len(steps) <= 8:
        raise Refused('Scenario requires 1-8 finite steps')
    for index, step in enumerate(steps):
        if not isinstance(step, dict):
            raise Refused('Scenario step requires an object')
        text = step.get('request')
        expected = step.get('observe', {})
        if 'input' in step:
            if set(step) != {'input', 'observe'}:
                raise Refused('Document step permits only input and operator-only observe')
            validate_document_input(step['input'])
        elif not isinstance(text, str) or not 1 <= len(text) <= 4000:
            raise Refused('Step request must be bounded text')
        if not isinstance(expected, dict):
            raise Refused('Unsupported observation schema')
        if 'mode' in expected:
            validate_reply_capture(expected, max_window_seconds=(1200 if stopped1578_capture_scenario(scenario) else 600))
            if index != len(steps) - 1:
                raise Refused('Bounded reply capture must be the final step; no continuation')
            if expected['max_messages'] > scenario['max_updates']:
                raise Refused('Bounded reply message budget exceeds the scenario update bound')
            if expected['window_seconds'] + REPLY_WINDOW_RESERVE > scenario['deadline_seconds']:
                raise Refused('Bounded reply window does not fit the scenario deadline with cleanup reserve')
            continue
        if set(expected) - {'text_equals', 'text_contains', 'documents'}:
            raise Refused('Unsupported observation schema')
        if 'text_equals' in expected and 'text_contains' in expected:
            raise Refused('Choose one precise text observation')
        if not any(expected.get(k) for k in ('text_equals', 'text_contains', 'documents')):
            raise Refused('First reply or quiet is not an oracle')
        for key in ('text_equals', 'text_contains'):
            if key in expected and (not isinstance(expected[key], str) or not 1 <= len(expected[key]) <= 8000):
                raise Refused('Text observation must be nonempty and bounded')
        docs = expected.get('documents', [])
        if not isinstance(docs, list) or len(docs) > 4:
            raise Refused('At most four expected documents per step')
        for doc in docs:
            if isinstance(doc, dict) and 'mode' in doc:
                validate_capture(doc)
                continue
            if not isinstance(doc, dict) or not isinstance(doc.get('sha256'), str) or not re.fullmatch('[a-f0-9]{64}', doc['sha256']) or type(doc.get('max_bytes')) is not int or not 1 <= doc['max_bytes'] <= MAX_FILE:
                raise Refused('Document requires exact hash and byte bound')
            if not isinstance(doc.get('caption_equals'), str) or len(doc['caption_equals']) > 1024:
                raise Refused('Document requires bounded exact caption')
            if 'contains_utf8' in doc and (not isinstance(doc['contains_utf8'], str) or len(doc['contains_utf8']) > 10000):
                raise Refused('Document content check invalid')
    return scenario


