        # Local operator pins are not evidence of product delivery or runtime adoption.
        fields = {'schema', 'operator', 'action_id', 'run_id', 'run_sha256',
                  'scenario_sha256', 'task_sha256', 'cursor_sha256', 'state_identity',
                  'consumer_identity', 'credential_identity', 'current_tuple',
                  'tester_id', 'peer_id', 'max_updates', 'clock'}
        if (not isinstance(plan, dict) or set(plan) != fields
                or plan['schema'] != 'friday.tester.reconcile-unknown.v1'
                or plan['operator'] != 'Root'
                or plan['tester_id'] != TESTER or type(plan['tester_id']) is not int
                or plan['peer_id'] != PEER or type(plan['peer_id']) is not int):
            raise Refused('Unknown reconciliation requires its exact named operator plan')
        for key in ('action_id', 'run_id'):
            self.store.run_path(plan[key])
        for key in ('run_sha256', 'scenario_sha256', 'task_sha256', 'cursor_sha256'):
            if not isinstance(plan[key], str) or not re.fullmatch('[a-f0-9]{64}', plan[key]):
                raise Refused('Unknown reconciliation requires exact unchanged evidence hashes')
        context = plan['current_tuple']
        if (not isinstance(context, dict) or set(context) != {'source', 'installed', 'layers', 'project', 'native', 'service_owner'}
                or any(type(context[k]) is not int or context[k] < 0
                       for k in ('source', 'installed', 'layers', 'project', 'native'))
                or context['native'] != 0 or context['service_owner'] != 'Root'):
            raise Refused('Root must explicitly bind the current product tuple; native must remain zero')
        # The public v1 reconciliation always remains <=120s. The separately
        # acknowledged NEW-effect admission reuses only these local evidence checks.
        if stopped1578_validation and not (continuation_validation and worker_file_validation):
            raise Refused('Extended clock requires the exact new stopped1578 worker validation')
        if m12_compact_validation and (not continuation_validation or worker_file_validation or stopped1578_validation):
            raise Refused('M12 finite1200 allowance requires its authenticated literal compact only')
        s05_finite_validation = s05_finite_plan is not None
        if s05_finite_validation:
            if (not continuation_validation or worker_file_validation or stopped1578_validation
                    or m12_compact_validation or S05_FINITE_HOOK is None
                    or not isinstance(s05_finite_plan, dict) or 's05_finite' not in s05_finite_plan
                    or plan['clock'] != s05_finite_plan.get('clock')
                    or plan['current_tuple'] != s05_finite_plan.get('current_tuple')):
                raise Refused('S05 extended clock requires its exact accepted finite continuation')
            S05_FINITE_HOOK.validate_plan(s05_finite_plan)
        clock_limit = (600 if s05_finite_validation else 1200 if m12_compact_validation else
            (((1800 - 60 if stopped1578_validation else 1200 - 60) if worker_file_validation else 300) if continuation_validation else 120))
        clock = plan['clock']
        if (not isinstance(clock, dict) or set(clock) != {'boot_id', 'origin_monotonic', 'deadline_monotonic'}
                or not isinstance(clock['boot_id'], str)
                or not re.fullmatch('[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}', clock['boot_id'])
                or any(type(clock[k]) not in (int, float) or not math.isfinite(clock[k])
                       for k in ('origin_monotonic', 'deadline_monotonic'))
                or not 0 <= clock['origin_monotonic'] < clock['deadline_monotonic'] <= clock['origin_monotonic'] + clock_limit):
            raise Refused('Bind one fresh reconciliation clock of at most 120 seconds')
