        # Renaming the grant or a copied run cannot reopen the same physical dispatch.
        key = digest(encoded(dict(tester_id=TESTER, peer_id=PEER, task_sha256=task['sha256'],
                                  scenario_sha256=run['scenario_sha256'], dispatched_at=dispatched,
                                  step=0, send_attempts=1)))
