        expected_window = {k: original[k] for k in ('scenario_sha256', 'step', 'send_attempts',
            'sent_message_id', 'sent_at', 'send_intent_at', 'send_dispatch_at',
            'send_timeout_seconds', 'capture_until', 'deadline')}
        expected_window.update(run_id=original_id,
            window_seconds=original['scenario']['steps'][0]['observe']['window_seconds'],
            ack=original['sent_api_ack_reference'], task=original['sent_task_reference'],
            continuation=original['continuation_reference'])
        if encoded(window) != encoded(expected_window):
            raise Refused('Original worker send-window custody changed')
