        if (task != original.get('request_metadata') or task.get('method') != 'sendDocument'
                or task.get('chat_id') != USERNAME or task.get('input_sha256') != upload['sha256']
                or task.get('input_bytes') != upload['stat']['size_bytes']
                or task.get('input_stat') != upload['stat']
                or any(task.get(k) != upload[k] for k in ('filename', 'mime_type', 'caption'))
                or task.get('scenario_sha256') != original['scenario_sha256']):
            raise Refused('Original worker physical request changed')
        ref = original['sent_api_ack_reference']
        ack = self.read_reference({k: ref[k] for k in ('basename', 'bytes', 'sha256')},
            'send-ack-' + original_id + '-0-1.json')
