    def worker_resume_material(self, plan, run, previous_plan, *, require_reply=False):
        spec = plan['new_task']
        fields = {'kind', 'nonce', 'worker', 'output_delivery', 'output_filename',
                  'output_mime_type', 'root_resume_reference', 'reply_to_message_id', 'original_input'}
        # Historical admissions remain immutable and readable. They may never be
        # used as a fresh dispatch without the new original-ACK proof.
        if isinstance(spec, dict) and set(spec) == fields - {'reply_to_message_id', 'original_input'}:
            if require_reply:
                raise Refused('New worker continuation requires original input reply proof')
            return self.legacy_worker_resume_material(plan, run, previous_plan)
        if (not isinstance(spec, dict) or set(spec) != fields or spec.get('kind') != 'resume-worker-file-task'
                or spec.get('output_delivery') != 'friday_result'
                or not isinstance(spec.get('nonce'), str) or not re.fullmatch('[a-f0-9]{32}', spec['nonce'])
                or spec['nonce'] == previous_plan.get('new_task', {}).get('nonce')
                or plan['predecessor'].get('semantic_review_reference') is not None):
            raise Refused('Exact worker missing-stage continuation schema required')
        if spec.get('reply_to_message_id') == 1616:
            return self.b63_csv_resume_material(plan, run, previous_plan, require_reply=require_reply)
        original, original_spec, ack, boundary_id, boundary_sha, decision = self.worker_resume_original(plan)
        # The immutable missing-stage case is not the current serial tester head.
        # Preserve its exact closure, independently of any later worker episode.
        boundary_raw = safe_read(self.store.run_path(boundary_id))
        if digest(boundary_raw) != boundary_sha:
            raise Refused('Original missing-worker boundary custody changed')
        boundary = json.loads(boundary_raw, object_pairs_hook=unique_object)
        if (boundary.get('id') != boundary_id
                or boundary.get('status') != 'EVIDENCE_READY' or boundary.get('send_state') != 'sent'
                or boundary.get('capture_window_complete') is not True
                or boundary.get('reply_outcome') != ('RECEIVED_UNGRADED' if spec['worker'] == 'DSH' else 'NO_RESPONSE_UNVERIFIED')
                or any(spec[k] != original_spec[k] for k in ('worker', 'output_delivery', 'output_filename', 'output_mime_type'))):
            raise Refused('Resume requires the exact closed original missing-worker boundary')
        # Existing serial admission validates the real immediate predecessor, its
