    def s444_bytes(self, path, limit=MAX_JSON):
        path = Path(path)
        home = Path('/home/jericho')
        if (not path.is_absolute() or '..' in path.parts or '.' in path.parts
                or not path.is_relative_to(home)):
            raise Refused('Protected absolute owner path required')
        for parent in (path.parent, *path.parent.parents):
            info = parent.lstat()
            if (not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode)
                    or info.st_mode & 0o022
                    or (parent.is_relative_to(home) and info.st_uid != os.getuid())):
                raise Refused('Protected owner path custody changed')
            if parent == home:
                break
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        def identity(info):
            return (info.st_dev,info.st_ino,info.st_uid,info.st_gid,info.st_mode,
                    info.st_nlink,info.st_size,info.st_mtime_ns,info.st_ctime_ns)
        with os.fdopen(fd, 'rb') as stream:
            before = os.fstat(stream.fileno())
            if (not stat.S_ISREG(before.st_mode) or before.st_uid != os.getuid() or before.st_gid != os.getgid()
                    or before.st_nlink != 1 or not 0 <= before.st_size <= limit
                    or stat.S_IMODE(before.st_mode) not in (0o400,0o600)):
                raise Refused('Protected private regular file required')
            data = stream.read(limit+1)
            if (len(data) != before.st_size or identity(os.fstat(stream.fileno())) != identity(before)
                    or identity(path.lstat()) != identity(before)):
                raise Refused('Protected file changed during read')
        return data

