    def a0_context_refusal_predecessors(self, plan, run, previous_plan, report, *, dispatch=False):
        # Exception for ONE known physical1539 refusal, not a reusable failure policy.
        # Source binding is intentionally unset until Root reviews post-window facts.
        binding = A0_CONTEXT_REFUSAL_BINDING
        reference = report['evidence']['pre_worker_context_refusal']
        if binding is None or encoded(reference) != encoded(binding):
            raise Refused('A0 context refusal proof remains UNBOUND')

        def read_evidence(ref):
            if (not isinstance(ref, dict) or set(ref) != {'path', 'bytes', 'sha256'}
                    or not isinstance(ref['path'], str) or not ref['path'].startswith('/')
                    or type(ref['bytes']) is not int or not 1 <= ref['bytes'] <= MAX_JSON
                    or not isinstance(ref['sha256'], str)
                    or not re.fullmatch('[a-f0-9]{64}', ref['sha256'])):
                raise Refused('Exact private context-refusal evidence required')
            raw = safe_read(ref['path'])
            if len(raw) != ref['bytes'] or digest(raw) != ref['sha256']:
                raise Refused('Context-refusal evidence changed')
            return json.loads(raw, object_pairs_hook=unique_object)

        proof = read_evidence(reference)
        # The shared serial head may have advanced through an independent DSH
        # operation. Validate that actual head and every immutable intervening
        # admission; never reopen the physical1539 successor claim.
        current, current_plan, _ = self.serial_predecessor(plan)
        if encoded(current) != encoded(run) or encoded(current_plan) != encoded(previous_plan):
            raise Refused('Context-refusal current serial predecessor changed')
        refusal_pin = plan['predecessor']
        visited = set()
        while current.get('id') != 'root-a0-outbound-aff30311676f':
            if current.get('id') in visited or len(visited) >= 64 or 'predecessor' not in current_plan:
                raise Refused('Current serial head does not descend from the exact context refusal')
            visited.add(current.get('id'))
            refusal_pin = current_plan['predecessor']
            current, current_plan, _ = self.serial_predecessor(current_plan)
        run, previous_plan = current, current_plan
