    def ordinary_memory_authority(self, plan):
        """Read only the narrow protected v4 grant; prose cannot opt into it."""
        path = self.store.root/'reconciliations'/('ordinary-'+digest(encoded(plan)))/'ROOT-AUTHORITY.json'
        parent = no_symlinks(path.parent).stat()
        if (not stat.S_ISDIR(parent.st_mode) or parent.st_uid != os.getuid()
                or stat.S_IMODE(parent.st_mode) != 0o700):
            raise Refused('Memory authority requires protected owner0700 parent')
        proof = json.loads(safe_read(path),object_pairs_hook=unique_object)
        if not isinstance(proof,dict) or proof.get('schema') != 'frw.bot-tester.ordinary-document-authority.v4':
            return None
        grant = proof.get('memory_case')
        expected = dict(schema='frw.bot-tester.ordinary-document-authority.v4',operator='Root',
            plan_sha256=digest(encoded(plan)),new_worker_authorized=False,
            original_unknown_replay_authorized=False,tester_sha256=digest(safe_read(__file__, MAX_SOURCE)),memory_case=grant)
        if encoded(proof) != encoded(expected):
            raise Refused('Exact memory authority, plan and installed consumer hash required')
        return validate_ordinary_memory_case(plan['new_task'],grant)

