    def ordinary_upgrade_reference(self, ref):
        # New proof leaves are private Root records, not executable modules. Atime
        # is excluded; owner/group/mode/link/identity/content must survive the read.
        if (not isinstance(ref, dict) or set(ref) != {'path', 'sha256'}
                or not isinstance(ref['path'], str) or not ref['path'].startswith('/')
                or not isinstance(ref['sha256'], str) or not re.fullmatch('[a-f0-9]{64}', ref['sha256'])):
            raise Refused('Exact retained-source proof reference required')
        path = no_symlinks(ref['path'])
        def identity(info):
            return tuple(getattr(info, k) for k in ('st_dev', 'st_ino', 'st_uid', 'st_gid',
                'st_mode', 'st_nlink', 'st_size', 'st_mtime_ns', 'st_ctime_ns'))
        before = identity(path.stat())
        raw = safe_read(path, MAX_FILE)
        if identity(path.stat()) != before or digest(raw) != ref['sha256']:
            raise Refused('Retained-source proof identity/hash changed')
        try:
            value = json.loads(raw, object_pairs_hook=unique_object)
        except (ValueError, UnicodeError):
            raise Refused('Retained-source proof must be unambiguous JSON') from None
        if not isinstance(value, dict):
            raise Refused('Retained-source proof object required')
        return value

