        # Root supplies small current binding records; re-read at every validation,
        # including dispatch. No cache of mutable session evidence or plan clocks.
        for key in ('source_session_evidence', 'current_session_evidence'):
            self.ordinary_upgrade_reference(conversation[key])
        routing = conversation['current_routing']
        if (not isinstance(routing, dict) or set(routing) != {'database_path','database_identity','scope','session_key'}
                or not isinstance(routing['database_path'], str)
                or not isinstance(routing['scope'], str) or not routing['scope'].startswith('/')
                or not isinstance(routing['session_key'], str) or not 1 <= len(routing['session_key']) <= 512):
            raise Refused('Exact current authoritative gateway routing binding required')
        database = no_symlinks(routing['database_path'])
        if (not database.is_relative_to(Path(pkg['home'])) or database.name != 'state.db'
                or not isinstance(routing['database_identity'], list)
                or len(routing['database_identity']) != 6
                or any(type(v) is not int for v in routing['database_identity'])):
            raise Refused('Routing database must be Root-bound inside this canonical home')
        def db_identity():
            info = database.stat()
            if (not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_nlink != 1
                    or stat.S_IMODE(info.st_mode) & 0o002):
                raise Refused('Unsafe authoritative routing database custody')
            return [info.st_dev,info.st_ino,info.st_uid,info.st_gid,info.st_mode,info.st_nlink]
        if db_identity() != routing['database_identity']:
            raise Refused('Authoritative routing database identity changed')
        connection = None
        try:
            connection = sqlite3.connect(database.as_uri()+'?mode=ro',uri=True,timeout=0.2)
            connection.execute('PRAGMA query_only=ON')
            query_deadline = time.monotonic() + 0.2
            connection.set_progress_handler(lambda: int(time.monotonic() >= query_deadline), 100)
            rows = connection.execute('SELECT entry_json FROM gateway_routing WHERE scope=? AND session_key=? LIMIT 2',
                (routing['scope'],routing['session_key'])).fetchall()
            if (db_identity() != routing['database_identity'] or len(rows) != 1
                    or not isinstance(rows[0][0], str) or len(rows[0][0].encode('utf-8')) > 65536):
                raise Refused('Exact current gateway routing row required')
            entry = json.loads(rows[0][0],object_pairs_hook=unique_object)
            if (not isinstance(entry, dict) or entry.get('session_key') != routing['session_key']
                    or entry.get('session_id') != conversation['current_session_id']
                    or entry.get('platform') != 'telegram' or entry.get('chat_type') != 'dm'):
                raise Refused('Current gateway conversation differs from the retained original')
        except (sqlite3.Error,ValueError,UnicodeError):
            raise Refused('Current authoritative gateway routing unavailable or changed') from None
        finally:
            if connection is not None:
                connection.close()

