    def continuation_receipt(self, run, *, with_prior=False):
        retained = getattr(self, '_retained_ordinary_admission', None)
        if retained is not None and retained[0] == digest(encoded(run)):
            return (*retained[1], None) if with_prior else retained[1]
        # The independently retained admission obliges this run even if its mutable
        # field is removed. The immutable send-window/receive chain also binds it.
        matches = []
        for path in self.store.root.glob('continue-*.json'):
            value = self.store.get(path)
            if value.get('plan', {}).get('new_run_id') == run['id']:
                raw = safe_read(path)
                matches.append((value, dict(basename=path.name, bytes=len(raw), sha256=digest(raw))))
        if not matches and 'continuation_reference' not in run:
            return None
        if len(matches) != 1 or run.get('continuation_reference') != matches[0][1]:
            raise Refused('Mandatory continuation admission missing or changed')
        value, ref = matches[0]; plan = value['plan']
        if (value.get('plan_sha256') != digest(encoded(plan))
                or run['scenario'] != plan['new_scenario'] or run['step'] != 0
                or run['id'] != plan['new_run_id']):
            raise Refused('Continuation task commitment changed')
        if run.get('id') == 'root-s05-d745ac09dcf2':
            self.s05_settled_partial(run, plan)
            # Exact historical inspection remains possible after the original
            # finite binding expires. guard still rejects its consumed old clock.
            return (plan, [], ref, None) if with_prior else (plan, [], ref)
        closed = getattr(self, '_closed_text_predecessor', None)
        if closed == (run['id'], plan):
            # serial_predecessor already pinned this exact immutable admission and
            # run. Verify its own task/ACK/window/receipts without walking its parent.
            # Current origin/credential/cursor authority remains checked by the NEW
            # plan's continuation_material before any effect, never by this shortcut.
            return (plan, [], ref, None) if with_prior else (plan, [], ref)
        old, updates, prior = self.continuation_material(plan)
        root = no_symlinks(self.store.root).stat()
        if (prior['state_identity'] != dict(path=str(self.store.root), device=root.st_dev, inode=root.st_ino, uid=root.st_uid)
                or root.st_uid != os.getuid() or stat.S_IMODE(root.st_mode) != 0o700):
            raise Refused('Continuation state root changed')
        for name, field in [('consumer.lock', 'consumer_identity'), ('tester-token', 'credential_identity')]:
            if input_stat(no_symlinks(self.store.root / name).stat()) != prior[field]:
                raise Refused('Continuation consumer or credential identity changed')
        return (plan, updates, ref, prior) if with_prior else (plan, updates, ref)

    def continue_unknown(self, plan, plan_sha256, consumer_fd, credential_fd):
        if s07_runtime_plan(plan):
            if S07_RUNTIME_HOOK is None:
                raise Refused('S07 ordinary300 runtime UNBOUND before admission')
            S07_RUNTIME_HOOK.bind_consumer(self, plan, consumer_fd, credential_fd)
        if 's05_finite' in plan:
            if S05_FINITE_HOOK is None:
                raise Refused('S05 executing finite consumer UNBOUND')
            S05_FINITE_HOOK.bind_consumer(self, plan, consumer_fd, credential_fd)
        if digest(encoded(plan)) != plan_sha256 or consumer_fd is None or credential_fd is None:
            raise Refused('Pinned canonical continuation plan and both locks required')
        old, updates, prior = self.continuation_material(plan, True, consumer_fd, credential_fd)
        self.recovery_guard(plan)
        # Original dispatch or immediate admitted attempt: one successor per physical
        # commitment, never reopened by new IDs/nonces/clock/scenario.
        parent = secure_dir(self.store.root / 'continuations')
        key = self.continuation_key(plan)
        (parent / key).mkdir(mode=0o700)
        for directory in (self.store.root, parent):
            fd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            try: os.fsync(fd)
            finally: os.close(fd)
        name = 'continue-' + key + '.json'
        value = dict(schema='friday.tester.closed-unknown-admission.v1', plan=plan,
                     plan_sha256=plan_sha256, original_outcome='UNKNOWN', original_replayed=False,
                     status='ONE_NEW_EFFECT_ADMITTED_NO_RETRY', response_binding='UNBOUND')
        if 'predecessor' in plan:
            value['predecessor_cursor'] = self.store.get(self.store.root / 'cursor.json')
        data = encoded(value)
        if (self.store.root / name).exists():
            raise Refused('Continuation admission already exists')
        self.store.write(self.store.root / name, data)
        ref = dict(basename=name, bytes=len(data), sha256=digest(data))
        run = self.new(plan['new_run_id'], plan['new_scenario'], continuation=ref)
        diagnostic_step = plan.get('new_scenario', {}).get('steps', [{}])[0]
        s10_diagnostic = (ordinary_s10_factual_text_capture(plan.get('new_task'),
            diagnostic_step, diagnostic_step.get('observe'), {}, 'diagnostic')
            or (len(plan.get('new_scenario', {}).get('steps', [])) == 1
                and ordinary_s11_factual_text_capture(plan.get('new_task'),
                    diagnostic_step, diagnostic_step.get('observe'), {}, 'diagnostic')))
        continuation_diagnostic = s10_diagnostic or s14_original_effect(plan.get('new_task'), plan.get('new_scenario')) or s15_original_effect(plan.get('new_task'), plan.get('new_scenario'))
        failure_phase = 'CONTINUATION_SEND'
        try:
            self.send(run)
            failure_phase = 'CONTINUATION_OBSERVE'
            self.observe(run)
        except BaseException as exc:
            if continuation_diagnostic:
                continuation_exception_diagnostic(self.store, plan_sha256, run['id'], exc, failure_phase)
            raise
        finally:
            if 's05_finite' in plan:
                try:
                    S05_FINITE_HOOK.cleanup(self, run)
                except BaseException as exc:
                    if continuation_diagnostic:
                        continuation_exception_diagnostic(self.store, plan_sha256, run['id'], exc, 'CONTINUATION_CLEANUP_S05')
                    raise
            if s07_runtime_plan(plan):
                try:
                    S07_RUNTIME_HOOK.cleanup(self, run)
                except BaseException as exc:
                    if continuation_diagnostic:
                        continuation_exception_diagnostic(self.store, plan_sha256, run['id'], exc, 'CONTINUATION_CLEANUP_S07')
                    raise
        return dict(run_id=run['id'], status=run['status'], original_outcome='UNKNOWN',
                    acceptance='NOT_ESTABLISHED', artifact_acceptance=run.get('artifact_acceptance', 'NOT_ESTABLISHED'))

    def send_ack_budget(self, run):
        admitted = self.continuation_receipt(run)
        if admitted is None:
            if 'new_ack_timeout_seconds' in run:
                raise Refused('Legacy or old run cannot override its original ACK bound')
            return REPLY_ACK_RESERVE
        value = admitted[0]['ack_timeout_seconds']
        if run.get('new_ack_timeout_seconds') != value or type(run.get('new_ack_timeout_seconds')) is not int:
            raise Refused('New operation ACK bound differs from its immutable admission')
        return value

    def continuation_document_match(self, run, message):
        admitted = self.continuation_receipt(run)
        if admitted is None or not isinstance(message, dict):
            return False
        spec = admitted[0]['new_task']; doc = message.get('document')
        if friday_result_task(spec):
            # The native result route replies to the frozen ingress message. A
            # fixed service caption never substitutes for that exact correlation.
            thread = message.get('reply_to_message')
            if (message.get('message_thread_id') is not None
                    or not isinstance(thread, dict) or type(thread.get('message_id')) is not int
                    or thread['message_id'] != (spec['original_result_message_id'] if spec['kind'] == 'existing-worker-result' and doc is not None else run['sent_message_id'])):
                return False
            if doc is None:
                return isinstance(message.get('text'), str) and message['text'].startswith(spec['nonce'])
            return (isinstance(doc, dict) and doc.get('file_name') == spec['output_filename']
                    and doc.get('mime_type') == spec['output_mime_type']
                    and isinstance(message.get('caption'), str)
                    and message['caption'] in FRIDAY_RESULT_CAPTIONS)
        if spec['kind'] == 'ordinary-document-task':
            thread=message.get('reply_to_message')
            return (message.get('message_thread_id') is None and isinstance(thread,dict)
                    and type(thread.get('message_id')) is int and thread['message_id']==run['sent_message_id']
                    and (isinstance(message.get('text'),str) or isinstance(doc,dict)))
        if spec['kind'] in ('distinct-new-conversation', 'approve-new-conversation', 'literal-script-command'):
            thread = message.get('reply_to_message')
            return (isinstance(thread, dict) and type(thread.get('message_id')) is int
                    and thread['message_id'] == run['sent_message_id']
                    and (spec['kind'] != 'literal-script-command' or message.get('message_thread_id') is None)
                    and isinstance(message.get('text'), str) and 'document' not in message)
        if spec['kind'] in ('contextual-text-followup', 'distinct-text-task') or (spec['kind'] in ('distinct-docx-create', 'distinct-worker-file-task') and doc is None):
            thread = message.get('reply_to_message', {})
            text = message.get('text')
            return (isinstance(thread, dict) and (not thread or (type(thread.get('message_id')) is int
                    and thread['message_id'] == run['sent_message_id']))
                    and isinstance(text, str) and text.startswith(spec['nonce'])
                    and 'document' not in message)
        thread = message.get('reply_to_message', {})
        # An explicit OTHER thread is never overridden by a nonce. Missing thread
        # may retain the exact nonce/name/MIME artifact, still UNBOUND/UNGRADED.
        return (isinstance(doc, dict) and isinstance(thread, dict)
                and (not thread or (type(thread.get('message_id')) is int
                     and thread['message_id'] == run['sent_message_id']))
                and doc.get('file_name') == spec['output_filename']
                and doc.get('mime_type') == ('application/zip' if spec['kind'] == 'distinct-worker-file-task' else UPLOAD_TYPES['docx' if spec['kind'] == 'distinct-docx-create' else 'xlsx'])
                and message.get('caption') == spec['nonce'])

    def import_quarantine(self, run):
        admitted = self.continuation_receipt(run)
        if admitted is None:
            return
        plan, updates, ref = admitted
        # A real fresh ACK/window/seed exists. Import arrival means HOST IMPORT time,
        # never historical network arrival. All imported records are UNBOUND.
        self.verify_capture_context(run)
        for update in updates:
            captures, processed = self.receive_inventory(run)
            uid = update['update_id']
            if uid not in processed:
                self.capture_reply(run, update)
                self.process(run, update)
            elif safe_read(self.store.captures / (str(uid) + '.json')) != encoded(update):
                raise Refused('Quarantine capture changed')
        captures, processed = self.receive_inventory(run)
        if any(u['update_id'] not in processed for u in updates):
            raise Refused('Quarantine handoff incomplete; no receive ACK permitted')

    def save(self, run):
        data = encoded(run)
        if len(data) > MAX_JSON:
            raise Refused('Run record exceeds original JSON cap; preserve prior durable state')
        self.store.write(self.store.run_path(run['id']), data)

    def keep_ack(self, run, result):
        data = encoded(result)
        representation = 'decoded-message-json'
        if len(data) > MAX_JSON:
            data = getattr(self.api, '_last_response', None)
            representation = 'botapi-wire-envelope-json'
            try:
                wire = json.loads(data) if isinstance(data, bytes) and len(data) <= MAX_JSON else None
                matching = isinstance(wire, dict) and wire.get('ok') is True and wire.get('result') == result
            except (ValueError, TypeError):
                matching = False
            if not matching:
                run.update(send_state='unknown', status='OVERSIZE_ACK')
                self.save(run)
                raise Refused('Acknowledgement cannot fit original JSON cap; never resend')
        name = 'send-ack-' + run['id'] + '-' + str(run['step']) + '-' + str(run['send_attempts']) + '.json'
        self.store.write(self.store.root / name, data)
        run['sent_api_ack_reference'] = {'basename': name, 'sha256': digest(data),
                                        'bytes': len(data), 'representation': representation}
        self.save(run)

    def load(self, name):
        run = self.store.get(self.store.run_path(name))
        if not isinstance(run, dict) or run.get('id') != name:
            raise Refused('Unknown or malformed run')
        validate_scenario(run.get('scenario'))
        if run.get('scenario_sha256') != digest(encoded(run['scenario'])):
            raise Refused('Stored scenario hash mismatch; never change an oracle after sending')
        if type(run.get('step')) is not int or not 0 <= run['step'] < len(run['scenario']['steps']):
            raise Refused('Stored step invalid')
        if type(run.get('deadline')) not in (int, float) or not math.isfinite(run['deadline']):
            raise Refused('Stored deadline invalid')
        expected = run['scenario']['steps'][run['step']]['observe']
        if reply_capture(expected) and run.get('send_state') == 'sent':
            if (type(run.get('sent_at')) not in (int, float)
                    or type(run.get('capture_until')) not in (int, float)
                    or run['capture_until'] != run['sent_at'] + expected['window_seconds']
                    or type(run.get('send_intent_at')) not in (int, float)
                    or run['send_intent_at'] > run['sent_at']
                    or run['sent_at'] + expected['window_seconds']
                       + REPLY_WINDOW_RESERVE > run['deadline']
                    or not self.valid_send_budget(run)):
                raise Refused('Stored bounded reply window changed or missing; never extended')
            self.verify_window(run)
        self.reply_run = run if reply_capture(expected) else None
        self.legacy_run = None if reply_capture(expected) else run
        return run

    def valid_send_budget(self, run):
        dispatched = run.get('send_dispatch_at')
        sent = run.get('sent_at')
        expected = run['scenario']['steps'][run['step']]['observe']
        return (type(dispatched) in (int, float) and math.isfinite(dispatched)
                and type(sent) in (int, float) and math.isfinite(sent)
                and run.get('send_timeout_seconds') == self.send_ack_budget(run)
                and dispatched <= sent <= dispatched + self.send_ack_budget(run)
                and dispatched + self.send_ack_budget(run) + expected['window_seconds']
                    + REPLY_WINDOW_RESERVE <= run['deadline'])

    def guard(self, run, *, http_cap=10):
        continuation = self.continuation_receipt(run, with_prior=True)
        if stopped1578_capture_scenario(run.get('scenario')) and (continuation is None
                or continuation[0].get('predecessor', {}).get('run_id') not in ('root-dsh-restored-dee7e7153f68','root-dsh-installed-380f198f2e21')
                or continuation[0].get('new_task', {}).get('kind') != 'resume-worker-file-task'
                or continuation[0]['new_task'].get('worker') != 'DSH'):
            raise Refused('Extended capture requires exact stopped1578 admission; no dispatch')
        monotonic_budget = http_cap
        if continuation is not None:
            monotonic_budget = self.recovery_guard(continuation[0], http_cap=http_cap)
            if run.get('send_state') in ('none', 'intent'):
                prior = continuation[3]
                if prior is None:
                    _, _, prior = self.continuation_material(continuation[0])
                if digest(safe_read(self.store.root / 'cursor.json')) != prior['cursor_sha256']:
                    raise Refused('Continuation receive cursor drifted before new outbound effect')
                self.cursor_offsets(self.store.get(self.store.root / 'cursor.json'))
        if (self.store.root / 'observer-stop.json').exists():
            raise Refused('Observer stopped; product cancellation is separate')
        if self.clock() >= run['deadline']:
            raise Refused('Original scenario deadline expired; product may still run')
        cooldown = self.store.get(self.store.root / 'cooldown.json', {})
        if self.clock() < cooldown.get('until', 0):
            raise Refused('retry_after cooldown active; no network request allowed')
        if continuation is not None:
            monotonic_budget = self.recovery_guard(continuation[0], http_cap=http_cap)  # Sample after durable validation reads.
        if continuation is not None and 's05_finite' in continuation[0]:
            if S05_FINITE_HOOK is None:
                raise Refused('S05 receiver cutoff UNBOUND')
            monotonic_budget = min(monotonic_budget, S05_FINITE_HOOK.receiver_remaining(continuation[0]))
        if continuation is not None and s07_runtime_plan(continuation[0]):
            if S07_RUNTIME_HOOK is None:
                raise Refused('S07 receiver cutoff UNBOUND')
            monotonic_budget = min(monotonic_budget, S07_RUNTIME_HOOK.receiver_remaining(continuation[0]))
        return min(http_cap, monotonic_budget, run['deadline'] - self.clock())

    def cooldown(self, exc):
        self.store.put(self.store.root / 'cooldown.json', {'until': self.clock() + exc.seconds, 'seconds': exc.seconds})

    def reply_window(self, run):
        expected = run['scenario']['steps'][run['step']]['observe']
        until = run.get('capture_until')
        if (not reply_capture(expected) or type(until) not in (int, float)
                or type(run.get('sent_at')) not in (int, float)
                or until != run['sent_at'] + expected['window_seconds']
                or type(run.get('send_intent_at')) not in (int, float)
                or run['send_intent_at'] > run['sent_at']
                or run['sent_at'] + expected['window_seconds']
                   + REPLY_WINDOW_RESERVE > run['deadline']
                or not self.valid_send_budget(run)):
            raise Refused('Bounded reply window missing or changed; never extended')
        return until

    def reply_timeout(self, run):
        until = self.reply_window(run)
        guarded = self.guard(run)
        # Check cutoff after the guard's durable reads, immediately before issuing
        # a network budget. Only this local boundary has a clean closed outcome.
        remaining = until - self.clock()
        if remaining <= 0:
            raise ReplyWindowClosed('Bounded reply window expired; outcome unverified')
        return min(guarded, remaining)

    def verify_window(self, run):
        # Independently protected outbound window/clock commitment, bound to the exact
        # run/scenario/step/task/ACK; changing both mutable run fields never extends it.
        expected = run['scenario']['steps'][run['step']]['observe']
        if not reply_capture(expected):
            return
        reference = run.get('sent_window_reference')
        name = 'send-window-' + run['id'] + '-' + str(run['step']) + '-' + str(run['send_attempts']) + '.json'
        if (not isinstance(reference, dict) or set(reference) != {'basename', 'bytes', 'sha256'}
                or reference.get('basename') != name or type(reference.get('bytes')) is not int
                or not 1 <= reference['bytes'] <= MAX_JSON):
            raise Refused('Bounded reply window commitment reference missing or invalid')
        raw = safe_read(self.store.root / name)
        if len(raw) != reference['bytes'] or digest(raw) != reference['sha256']:
            raise Refused('Bounded reply window commitment custody mismatch')
        try:
            commitment = json.loads(raw, object_pairs_hook=unique_object)
        except (ValueError, UnicodeError):
            raise Refused('Bounded reply window commitment is not unambiguous JSON') from None
        if (not isinstance(commitment, dict)
                or commitment.get('run_id') != run['id']
                or commitment.get('scenario_sha256') != run['scenario_sha256']
                or commitment.get('step') != run['step']
                or commitment.get('send_attempts') != run['send_attempts']
                or commitment.get('sent_message_id') != run.get('sent_message_id')
                or type(commitment.get('sent_at')) not in (int, float)
                or type(commitment.get('send_intent_at')) not in (int, float)
                or commitment['send_intent_at'] > commitment['sent_at']
                or commitment.get('send_intent_at') != run.get('send_intent_at')
                or type(commitment.get('capture_until')) not in (int, float)
                or commitment.get('window_seconds') != expected['window_seconds']
                or commitment['capture_until'] != commitment['sent_at'] + expected['window_seconds']
                or commitment.get('deadline') != run['deadline']
                or commitment['sent_at'] + expected['window_seconds']
                   + REPLY_WINDOW_RESERVE > commitment['deadline']
                or commitment.get('send_dispatch_at') != run.get('send_dispatch_at')
                or commitment.get('send_timeout_seconds') != self.send_ack_budget(run)
                or not self.valid_send_budget(run)
                or commitment.get('ack') != run.get('sent_api_ack_reference')
                or commitment.get('task') != run.get('sent_task_reference')
                or commitment.get('continuation') != run.get('continuation_reference')
                or run.get('sent_at') != commitment['sent_at']
                or run.get('capture_until') != commitment['capture_until']):
            raise Refused('Bounded reply window commitment does not bind the exact run/clock/ack')

    def check_reply_text_receipt(self, message, observation, raw):
        """The common custody check of ONE reply_text receipt.

        The receipt names the field the model's wording came from. A receipt WITHOUT that
        marker is an OLD receipt: it keeps confirming message.text exactly, so the
        historical receipts and their hashes stay valid and unchanged. A receipt WITH the
        marker is checked against exactly the field it names, and a substituted caption or
        a substituted source is refused.

        The raw update's bytes and hash, the message id, the date and the protected text
        digest are checked here, so the wording can never be re-derived from anything but
        the retained raw bytes.
        """
        raw_reference = observation.get('raw_update', {})
        source = observation.get('text_source')
        if source is None:
            # OLD receipt: message.text only, as before
            wording = message.get('text')
        else:
            if source not in ('text', 'caption'):
                raise Refused('Reply text source is not a known field')
            wording = message.get(source)
        if (not isinstance(raw_reference, dict)
                or raw_reference.get('basename') != str(observation['update_id']) + '.json'
                or len(raw) != raw_reference.get('bytes')
                or digest(raw) != raw_reference.get('sha256')
                or not isinstance(wording, str)
                or wording != observation.get('text')
                or digest(wording.encode('utf-8')) != observation.get('text_sha256')
                or message.get('date') != observation.get('date')):
            raise Refused('Reply text raw/receipt custody changed')

