    def ordinary_independent_admission(self, name, scenario):
        expected_sha = self.ORDINARY_INDEPENDENT_SCENARIOS.get(name)
        if expected_sha is None:
            return None
        reference = self.ORDINARY_INDEPENDENT_AUTHORITY
        raw = safe_read(Path(reference['path']))
        document = json.loads(raw, object_pairs_hook=unique_object)
        now = self.clock()
        if (len(raw) != reference['bytes'] or digest(raw) != reference['sha256']
                or encoded(document) != raw
                or document.get('schema') != 'frw.Root.ordinary-independent-history-admission.v1'
                or document.get('authority_id') != 'UNBOUND'
                or document.get('operator') != 'Root' or document.get('accepted') is not True
                or document.get('run_scenarios') != self.ORDINARY_INDEPENDENT_SCENARIOS
                or digest(encoded(scenario)) != expected_sha
                or type(document.get('created_at')) not in (int, float)
                or type(document.get('expires_at')) not in (int, float)
                or not document['created_at'] <= now < document['expires_at']
                or document.get('boot_id') != Path('/proc/sys/kernel/random/boot_id').read_text().strip()
                or document.get('new_independent_inputs_only') is not True
                or document.get('no_old_task_replay') is not True
                or document.get('old_rows_modified') is not False
                or document.get('unknown_effects_resolved') is not False
                or document.get('product_or_B00_acceptance') is not False
                or document.get('new_trial_for_historical_task') is not False
                or not isinstance(document.get('history'), dict) or len(document['history']) < 40):
            raise Refused('Exact ordinary independent admission required')
        gateway = document.get('gateway', {})
        state_path = no_symlinks(Path(gateway['state_path']))
        state_info = state_path.stat()
        state_identity = (state_info.st_dev, state_info.st_ino, state_info.st_mode,
                          state_info.st_nlink, state_info.st_uid, state_info.st_gid,
                          state_info.st_size, state_info.st_mtime_ns, state_info.st_ctime_ns)
        if state_info.st_uid != os.getuid() or stat.S_IMODE(state_info.st_mode) & 0o002:
            raise Refused('Unsafe gateway state ownership or write mode')
