    def ordinary_independent_predecessor_checked(self, binding):
        """Require the immediate predecessor's custody and accepted independent review."""
        if (type(binding) is not dict
                or set(binding) != {'run_id', 'scenario_sha256', 'run_record_sha256',
                                    'review', 'review_schema', 'initially_absent'}
                or type(binding['run_id']) is not str
                or type(binding['scenario_sha256']) is not str
                or not re.fullmatch('[a-f0-9]{64}', binding['scenario_sha256'])
                or (binding['run_record_sha256'] is not None
                    and (type(binding['run_record_sha256']) is not str
                         or not re.fullmatch('[a-f0-9]{64}', binding['run_record_sha256'])))
                or type(binding['review']) is not dict
                or set(binding['review']) != {'path', 'sha256'}
                or type(binding['review']['path']) is not str
                or (binding['review']['sha256'] is not None
                    and (type(binding['review']['sha256']) is not str
                         or not re.fullmatch('[a-f0-9]{64}', binding['review']['sha256'])))
                or type(binding['review_schema']) is not str
                or type(binding['initially_absent']) is not bool):
            raise Refused('Exact ordered predecessor admission required')
        previous_id = binding['run_id']
        previous_path = self.store.run_path(previous_id)
        try:
            previous_raw = safe_read(previous_path)
        except OSError:
            raise Refused('Ordered predecessor run required before save or API') from None
        previous = json.loads(previous_raw, object_pairs_hook=unique_object)
        if (previous.get('id') != previous_id
                or previous.get('scenario_sha256') != binding['scenario_sha256']
                or previous.get('status') != 'EVIDENCE_READY'
                or previous.get('send_state') != 'sent'
                or previous.get('send_attempts') != 1
                or encoded(previous) != previous_raw):
            raise Refused('Ordered predecessor custody required')
        self.verify_reply_custody(previous)
        review_reference = binding['review']
        try:
            review_raw = safe_read(Path(review_reference['path']), private=False)
        except OSError:
            raise Refused('Ordered predecessor independent review required before save or API') from None
        review = json.loads(review_raw, object_pairs_hook=unique_object)
        if (review.get('schema') != binding['review_schema']
                or review.get('run_id') != previous_id
                or review.get('scenario_sha256') != binding['scenario_sha256']
                or review.get('semantic') != 'PASS'
                or review.get('custody') != 'PASS'
                or review.get('custody_evidence', {}).get('run_record_sha256') != digest(previous_raw)
                or (binding['run_record_sha256'] is not None
                    and binding['run_record_sha256'] != digest(previous_raw))
                or (review_reference['sha256'] is not None
                    and review_reference['sha256'] != digest(review_raw))):
            raise Refused('Ordered predecessor review run binding required')
        return previous

    def ordinary_independent_history_row(self, admission, previous):
        if not isinstance(admission, dict) or not isinstance(previous, dict):
            return False
        reference = admission['history'].get(previous.get('id'))
        if not isinstance(reference, dict):
            return False
        raw = safe_read(self.store.run_path(previous['id']))
        if (digest(raw) != reference['sha256'] or encoded(previous) != raw
                or previous.get('status') != reference['status']
                or previous.get('send_state') != reference['send_state']
                or previous.get('deadline') != reference['deadline']
                or self.clock() < previous['deadline']
                or reference['new_effect_replay_authorized'] is not False
                or reference['unknown_retained'] is not (previous['send_state'] == 'unknown')):
            return False
        return True

    def ordinary_independent_current_rows(self, admission, current_run_id):
        for path in self.store.runs.glob('*.json'):
            if path == self.store.run_path(current_run_id):
                continue
            previous = self.store.get(path)
            if ((previous.get('status') not in ('EVIDENCE_READY', 'STOPPED', 'FAILED')
                 or previous.get('send_state') in ('intent', 'unknown'))
                    and not self.ordinary_independent_history_row(admission, previous)):
                raise Refused('Current unresolved run outside exact independent history')
        return True

