def _a0_inventory_with1610(self, snapshot, baseline=None):
    rows = snapshot.get('selected') if isinstance(snapshot, dict) else None
    if not isinstance(rows, list):
        return _A0_INVENTORY_BEFORE1610(self, snapshot, baseline)
    present = [row for row in rows if row.get('reference') == _A0_1610_REF]
    if not present:
        return _A0_INVENTORY_BEFORE1610(self, snapshot, baseline)
    _, _, _, _, actual = _a0_1610_proof(self)
    _a0_1610_need(present == [actual], 'Closed1610 inventory row changed')
    historical = dict(snapshot, selected=[row for row in rows if row.get('reference') != _A0_1610_REF],
                      validated_jobs=snapshot['validated_jobs'] - 1)
    oldbase = None if baseline is None else {key: value for key, value in baseline.items() if key != _A0_1610_REF}
    result = _A0_INVENTORY_BEFORE1610(self, historical, oldbase)
    result[_A0_1610_REF] = actual
    if baseline is not None and _A0_1610_REF in baseline:
        _a0_1610_need(encoded(result) == encoded(baseline), 'Full closed1610 inventory changed')
    return result


